window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":83,"source":"خطبه 83.docx","mode":"explicit-parts","parts":["خطبه ۸۳\nبخش اول\nمتن:\nصفتُه جَلّ شأنُه‏:\nالْحَمْدُ لِلَّهِ الَّذِي عَلَا بِحَوْلِهِ وَ دَنَا بِطَوْلِهِ، مَانِحِ كُلِّ غَنِيمَةٍ وَ فَضْلٍ وَ كَاشِفِ كُلِّ عَظِيمَةٍ وَ أَزْلٍ؛ أَحْمَدُهُ عَلَى عَوَاطِفِ كَرَمِهِ وَ سَوَابِغِ نِعَمِهِ، وَ أُومِنُ بِهِ أَوَّلًا بَادِياً وَ أَسْتَهْدِيهِ قَرِيباً هَادِياً، وَ أَسْتَعِينُهُ قَاهِراً قَادِراً، وَ أَتَوَكَّلُ عَلَيْهِ كَافِياً نَاصِراً. وَ أَشْهَدُ أَنَّ مُحَمَّداً صلی الله علیه وآله عَبْدُهُ وَ رَسُولُهُ أَرْسَلَهُ لِإِنْفَاذِ أَمْرِهِ وَ إِنْهَاءِ عُذْرِهِ وَ تَقْدِيمِ نُذُرِهِ‏.\nالوصية بالتقوى: \nأُوصِيكُمْ عِبَادَ اللَّهِ بِتَقْوَى اللَّهِ الَّذِي ضَرَبَ الْأَمْثَالَ وَ وَقَّتَ لَكُمُ الْآجَالَ وَ أَلْبَسَكُمُ الرِّيَاشَ وَ أَرْفَغَ لَكُمُ الْمَعَاشَ وَ أَحَاطَ بِكُمُ الْإِحْصَاءَ وَ أَرْصَدَ لَكُمُ الْجَزَاءَ وَ آثَرَكُمْ بِالنِّعَمِ السَّوَابِغِ وَ الرِّفَدِ الرَّوَافِغِ وَ أَنْذَرَكُمْ بِالْحُجَجِ الْبَوَالِغِ، فَأَحْصَاكُمْ عَدَداً وَ وَظَّفَ لَكُمْ مُدَداً فِي قَرَارِ خِبْرَةٍ وَ دَارِ عِبْرَةٍ أَنْتُمْ مُخْتَبَرُونَ فِيهَا وَ مُحَاسَبُونَ عَلَيْهَا.\nالتنفير من الدنيا:\nفَإِنَّ الدُّنْيَا رَنِقٌ مَشْرَبُهَا رَدِغٌ مَشْرَعُهَا يُونِقُ مَنْظَرُهَا وَ يُوبِقُ مَخْبَرُهَا، غُرُورٌ حَائِلٌ وَ ضَوْءٌ آفِلٌ وَ ظِلٌّ زَائِلٌ وَ سِنَادٌ مَائِلٌ\nترجمه:\nستايش مخصوص خداوندى است که با قدرتش برترى يافته و با نعمتش به بندگانش نزديک شده! خداوندى که بخشنده هر غنيمت و فضلى است و برطرف کننده هر بلا و مصيبتى! او را ستايش مى کنم بر کَرَم هاى پى در پى و نعمتهاى فراوانش، و به او ايمان مى آورم که مبدأ هستى است و ظاهر و آشکار است و از وى هدايت مى طلبم که نزديک و راهنما است، و از او يارى مى جويم که پيروز و توانا است، و بر او توکّل مى کنم که از ديگران بى نيازم کرده و يارى مى دهد.\nو گواهى مى دهم که محمد(صلى الله عليه وآله) بنده و فرستاده او است. او را فرستاد تا فرمانش را اجرا کند و اتمام حجّت نمايد و (بندگان را در برابر مخالفت فرمانش) بيم دهد.\nاى بندگان خدا! شما را به تقوا و ترس از خدايى که مَثَل هايى براى بيان حقايق ذکر کرده است، سفارش مى کنم! همان خداوندى که مدّت زندگى شما را معيّن فرموده است و لباس هاى زيبا بر شما پوشانيد و زندگى پر وسعت به شما بخشيد;\nخدايى که حساب و شمارش را بر گِرد شما قرار داد و جزا را مراقب شما نمود (تمام اعمال شما تحت حساب است و پاداش و کيفر الهى در انتظار شما است) همان کس که شما را با نعمت هاى گسترده و بخشش هاى وسيعِ (خود) مقدّم داشته و با دلايل روشن و رسا، شما را (از مخالفت فرمانش) بيم داده است، تعداد شما را به خوبى مى داند و مدّتهاى کوتاهى براى توقّف در اين جهان براى شما مقرّر فرموده، جهانى که قرارگاه آزمايش و سراى عبرت است; در آن آزموده مى شويد و در برابر اعمالى که انجام داده ايد، حسابرسى خواهيد شد.\nدنيا آبشخورش تيره و ورودى به اين آبگاه، پُر گِل ولاى است. چشم اندازش فريبنده و باطن آن کشنده است. فريبى است گذرا! و پرتوى است، ناپايدار! و سايه اى است، زوال پذير! و تکيه گاهى است، نااستوار! \nتفسیر:\n    خطبهٔ غراء\nخطبه‌ها در زبان روایات نام‌های خاصی دارند؛ مانند شقشقیه، جهادی و متقین. این خطبه نیز به «غراء» (به معنای درخشان و شریف) معروف است؛ چرا که سخنی بسیار روشن، گویا و بلیغ است که نوری پیش پای انسان روشن می‌سازد و دل‌ها را به خود جذب می‌کند.\nاگر برای خطبه‌ها، نامه‌ها و حکمت‌های نهج‌البلاغه هفت‌خوان در نظر بگیریم، خوان نخست همان خطبهٔ اول است و خوان دوم، همین خطبهٔ غراء است که هم مضامین بلندی دارد و هم واژگان آن سرشار از فصاحت و بلاغت است.\nابن ابی‌الحدید که خود ادیبی برجسته است و با ادبیات سروکار دارد، در شرح خود دربارهٔ این خطبه چنین می‌نویسد: «بدانید برای من و کسانی که با ادبیات عرب آشنایی دارند، هیچ شکی نیست که امیرالمؤمنین افصح و ابلغ مردمان است. اگر پروردگار و پیامبر را استثنا کنیم، هیچ‌کس به گردپای او نمی‌رسد؛ چرا که علی (ع) گوی سبقت را در واژگان عربی ربوده است.»\nشأن صدور خطبه\nروزی امیرالمؤمنین (ع) در تشییع‌جنازهٔ شخصی شرکت کردند. پس از خاک‌سپاری متوفی، خانواده و خویشاوندان او بی‌قراری و ناراحتی می‌کردند. حضرت فرمود: «اگر می‌دانستید او چه مسیری را طی می‌کند و با چه صحنه‌هایی روبه‌رو می‌شود، از یادتان می‌رفت که عزیزی را از دست داده‌اید.» در آن حال که دل‌های حاضران آماده و پذیرای سخن بود، حضرت فرمود:\n«الْحَمْدُ لِلَّهِ الَّذِی عَلَا بِحَوْلِهِ»\nستایش مخصوص خدایی است که به سبب قدرت و نیروی خود، بلندمرتبه است.\nمعنای دقیق «حول»، حائل و فاصله انداختن است؛ یعنی قدرتی که می‌تواند میان دو چیز جدایی و فاصله بیندازد. هرچه این قدرت بیشتر باشد، علوّ درجه نیز بیشتر است.\n«وَ دَنَا بِطَوْلِهِ»\nو ستایش مخصوص خدایی است که به بخشش و عطای خود، بسیار نزدیک است.\nمگر دور یا نزدیک بودن خداوند، بعد مکانی دارد؟ دور بودن او به‌خاطر عظمت و قدرت اوست و نزدیک بودنش به‌خاطر بخشش و عطاست.\n«مَانِحِ کلِّ غَنِیمَةٍ وَ فَضْلٍ»\nبخشنده‌ای که هر بهره و فضلی را عطا می‌کند.\nهیچ لطف و رحمتی را جز در درگاه خدا نمی‌توان یافت و هر بهره‌ای را باید تنها از او طلب کرد.\n«وَ کاشِفِ کلِّ عَظِیمَةٍ وَ أَزَلٍ»\nو برطرف‌کنندهٔ هر گرفتاری بزرگ و سختیِ شدید است.\nخداوند دفع‌کنندهٔ هر رنج بزرگی است. دو عبارت «مانح» و «کاشف»، دو جلوه از قدرت و نعمت الهی هستند. نمود این قدرت و نعمت چیست؟ خدایی که فضل می‌رساند و گرفتاری را دور می‌کند؛ پس او سزاوار حمد و سپاس است. خدای مهربان که لطف، رحمت و قدرت مطلق است و عطا می‌کند (نه اینکه قدرت داشته باشد اما کاری نکند)، باید ستایش شود.\n«أَحْمَدُهُ عَلَی عَوَاطِفِ کرَمِهِ وَ سَوَابِغِ نِعَمِهِ»\nاو را بر کرم پی‌درپی و فراوانش، و نعمت‌های کامل و سرشارش می‌ستایم.\n«عواطف کرمه» یعنی کرم و بخشش پروردگار پیوستگی و عطوفت دارد؛ معنای دوم آن است که به سبب رحمتش، دل‌ها به او معطوف و متمایل می‌شوند. «سوابغ» نیز یعنی نعمت‌های او کامل و تمام است. این‌گونه نیست که خداوند بخشی از نعمت را بدهد و بخش دیگر را دریغ کند؛ بلکه آنچه را انسان برای هدایت و سعادت نیاز دارد، آماده و مهیا ساخته است. هرگز راه رشد بر پویندگان بسته نیست و پروردگار در بخشش خود در پی منت‌گذاردن نیست.\n«وَ أُومِنُ بِهِ أَوَّلًا بَادِیاً»\nو به او ایمان دارم که آغازگر نخستینِ هستی بوده است.\nتنها کسی را باید به پروردگاری پذیرفت که سابقهٔ عدم و نیستی نداشته باشد؛ یعنی خدایی که ازلی، ابدی و سرمدی باشد. چنین خدایی شایستهٔ پرستش و ایمان‌آوردن است.\n«وَ أَسْتَهْدِیهِ قَرِیباً هَادِیاً»\nو از او راهنمایی می‌جویم که راهنمایی نزدیک و هدایتگر است.\nویژگی اول این است که از کسی طلب هدایت می‌کنم که نزدیک و در دسترس است؛ او صدا، سکوت، اسرار و نجوای درون را می‌شنود. ویژگی دوم این است که او در پی هدایت و دستگیری است، نه مچ‌گیری.\n«وَ أَسْتَعِینُهُ قَاهِراً قَادِراً وَ أَتَوَکلُ عَلَیهِ کافِیاً نَاصِراً»\nو از او یاری می‌طلبم که چیره و تواناست و ضعفی در او راه ندارد، و به او توکل می‌کنم که بی‌نیازکننده و یاری‌دهنده است.\nاگر انسان کار خود را به خدا بسپارد، او سرپرست و کفیل انسان می‌شود و همهٔ امور را به بهترین شکل تدبیر و سرپرستی می‌کند.\n«وَ أَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَ رَسُولُهُ»\nو شهادت می‌دهم که محمد (درود خدا بر او و خاندانش باد) بنده و فرستادهٔ اوست.\n«أَرْسَلَهُ لِإِنْفَاذِ أَمْرِهِ»\nاو را فرستاد تا فرمان‌هایش را در زمین اجرا کند.\n«وَ إِنْهَاءِ عُذْرِهِ»\nو فرستاده شد تا راه هرگونه عذر و بهانه‌ای را ببندد.\nپیامبر فرستاده شد تا با دلایل عقلی، نقلی، معجزه و سخن‌گفتن از پیامبران گذشته، حقایق را به طور عمیق و دقیق بیان کند تا راه توجیه و عذر بر مردم بسته شود. این‌ها اهداف بعثت هستند که ما نیز باید آن‌ها را بپذیریم؛ هرچه بیشتر فرمان‌های الهی را اجرا کنیم، رسالت را یاری کرده‌ایم و هرچه بیشتر عذرتراشی کنیم، سد راه اهداف پیامبر شده‌ایم.\n«وَ تَقْدِیمِ نُذُورِهِ»\nو بیم دادن‌هایش را پیش بفرستد.\nهدف دیگر از فرستادن پیامبر این بود که پیش از آنکه دیر شود و مردم وارد دوزخ شوند، هشدارها را به آنان ابلاغ کند؛ یعنی پیش از آنکه کار از کار بگذرد، عاقبت گناه و بی‌تقوایی را بازگو نماید.\n«أُوصِیکمْ عِبَادَ اللَّهِ بِتَقْوَی اللَّهِ الَّذِی ضَرَبَ لَکمُ الْأَمْثَالَ»\nای بندگان خدا، شما را به تقوا و خداترسی سفارش می‌کنم؛ همان خدایی که برای شما مثل‌ها زده است.\nتقوا امری مستحب نیست که بود و نبودش یکسان باشد. از گناه بپرهیزید؛ همانی که نمونه‌های آشکار آن را در قرآن از زبان اهل‌بیت بیان فرموده است. قرآن کتاب داستان‌سرایی نیست، بلکه تمثیل‌ها و اشارات آن برای عبرت‌گرفتن است. پروردگار حقیقتِ معقول بهشت را در قالب چند مثال ملموس بیان کرد تا آن را درک کنیم، بچشیم و حرکت کنیم؛ چرا که هدف، هدایت انسان است و حقایق ناملموس جهانِ دیگر در قالب مثال بیان می‌شوند تا فهم آن‌ها آسان شود.\n«وَ وَقَّتَ لَکمُ الْآجَالَ»\nو برای مرگ شما زمان معینی قرار داده است.\nیاد مرگ و توجه به این رفتنِ قطعی و حتمی، انسان را اهل تقوا می‌سازد.\n«وَ أَلْبَسَکمُ الرِّیاشَ»\nو به شما لباس و پوشش عنایت کرد.\nنعمت لباس ظاهری، انسان را از برهنگی نجات داد و مایع پوشاندن عیوب شد. به‌عنوان یکی از جلوه‌های عملی، تقوا را رعایت کنید؛ چرا که اگر لباس نبود، بی‌آبرویی پدید می‌آمد. ازسوی‌دیگر، تقوا خود یک پوشش باطنی است که خدا برای انسان در نظر گرفته و انسان باید آن را بر تن کند.\n«وَ أَرْفَعَ لَکمُ الْمَعَاشَ»\nو وسایل زندگی و معیشت شما را وسعت بخشید.\nهرچه امکانات و معیشت انسان وسعت یابد، باید تقوای او نیز بیشتر شود. خدا معیشت را وسعت داد تا بیشتر یاد شود، نه اینکه فراموش گردد. یکی از عیوب بزرگ انسان این است که هرچه امکانات مادی او بیشتر می‌شود، فاصله‌اش از پروردگار افزون می‌گردد.\n«وَ أَحَاطَ بِکمُ الْإِحْصَاءَ وَ أَرْصَدَ لَکمُ الْجَزَاءَ»\nو حسابرسی خود را بر شما احاطه داده و پاداش و کیفر شما را در کمین قرار داده است.\nتقوا داشته باشید که کارهایتان همواره در حال محاسبه است و حسابگران اعمال، گرداگرد شما را فراگرفته‌اند. بندگان در تیررس نگاه خدا و فرشتگان حسابرس هستند و محال است عملی محاسبه نشود. افزون بر این محاسبه، در برابر عمل شما ثواب یا کیفری در کمین نشسته است تا به شما برسد.\n«وَ آثَرَکمْ بِالنِّعَمِ السَّوَابِغِ»\nو نعمت‌های فراوان و کامل خود را به شما اختصاص داد.\nآیا همین که انسان‌ها از نعمت‌های بزرگ برخوردار شده‌اند، دلیل کافی برای پیشه‌کردن تقوای بیشتر نیست؟ هرچه نعمت افزون شود، تقوا نیز باید بیشتر شود، نه گناه و سرکشی.\n«وَ الرِّفَدِ الرَّوَافِعِ وَ أَنْذَرَکمْ بِالْحُجَجِ الْبَوَالِغِ»\nو بخشش‌های بزرگ را در اختیارتان گذاشت و با دلیل‌های رسا و آشکار شما را بیم داد.\nخداوند نه‌تنها نعمت‌های گسترده را عطا کرد، بلکه با دلایل آشکار (مانند قرآن، کتب آسمانی، فرستادن علما و براهین عقلی) هشدار داد؛ ازاین‌رو ممکن نیست در برابر این‌همه نعمت، از انسان مسئولیتی نخواهد. با در اختیار گذاشتن این ابزارها، انتظار خروجی و رشد دارند. پس باوجود این نعمت‌ها باید باتقوا بود؛ چرا که همواره در حال رصدشدن هستیم.\n«فَأَحْصَاکمْ عَدَداً»\nپس شمار شما را به‌دقت نگاشت.\nتقوای خدایی را پیشه کنید که تعداد شما را محاسبه می‌کند. در میان میلیاردها انسان از آغاز تا انجام آفرینش، خدا به تک‌تک افراد توجه دارد و هیچ‌کس را فراموش نمی‌کند؛ هم شمار افراد و هم اعمال آنان از دایرهٔ محاسبه بیرون نیست. در عبارت قبلی عمل مورد محاسبه بود که نه گم می‌شود و نه خللی در آن راه می‌یابد، و در این عبارت مشخص می‌شود که در آمار و شمارش افراد نیز هیچ اشتباهی رخ نمی‌دهد.\n«وَ وَظَّفَ لَکمْ مُدَداً»\nو برای زندگی شما مدت معینی مقرر داشت.\n«فِی قَرَارِ خِبْرَةٍ وَ دَارِ عِبْرَةٍ»\nمدت عمر را در این قرارگاه آزمایش و سرای عبرت مقدر کرد.\nکسی که بداند در جلسهٔ امتحان نشسته است، با آمادگی متناسب حاضر می‌شود؛ و تقوا، همان آمادگی برای آزمون است. این جلسه ناظر و مراقب دارد و سرای پندگرفتن است. مدت عمر کوتاه است و هرگونه که سپری شود، بازگشتی ندارد؛ پس باید پاسخ‌گو بود.\n«أَنْتُمْ مُخْتَبَرُونَ فِیهَا وَ مُحَاسَبُونَ عَلَیهَا»\nشما در دنیا مورد آزمایش قرار می‌گیرید و بر اساس آن محاسبه می‌شوید.\nمحاسبهٔ آخرت بر پایهٔ عملکرد دنیاست؛ زیرا بیرون از دنیا عملی صورت نمی‌گیرد که پاداش یا کیفری به آن تعلق بگیرد. دنیا هم محل آزمون است و هم نتیجه را مشخص می‌سازد؛ فردای انسان ثمرهٔ تلاش امروز اوست. کسی که بداند در معرض امتحان قرار دارد و با هر عملی رصد می‌شود، نمی‌تواند بی‌تفاوت باشد و مراقبت نکند.\n«فَإِنَّ الدُّنْیا رَنِقٌ مَشْرَبُهَا، رَدِغٌ مَشْرَعُهَا»\nهمانا آبِ نوشیدنی دنیا تیره و کدر است و مسیر ورود به آبشخور آن، گل‌آلود و لغزنده است.\nویژگی دنیا این است که نه آب زلالی دارد و نه مسیر همواری؛ و هر دو ویژگی سبب زمین‌گیر شدن انسان می‌شود.\n«یونِقُ مَنْظَرُهَا وَ یوبِقُ مَخْبَرُها»\nظاهر و چشم‌انداز دنیا زیبا و شگفت‌انگیز است، اما باطن آن هلاک‌کننده و کشنده است.\nدر جایی فرمودند دنیا مانند مار خوش‌خط و خالی است که پوستی نرم و مخملی دارد، اما درون آن سمی کشنده است.\n«غُرُورٌ حَائِلٌ، وَ ضَوْءٌ آفِلٌ، وَ ظِلٌّ زَائِلٌ، وَ سِنَادٌ مَائِلٌ»\nفریبی است زودگذر، نوری است رو به افول، سایه‌ای است نابودشدنی و تکیه‌گاهی است کج و ریختنی.\nدنیا با چنین ویژگی‌هایی، هر روز با رنگ و جلوه‌ای نو فریب می‌دهد و سپس غروب می‌کند؛ پس به این دیوارهٔ ریختنی دنیا تکیه نزنید.\n«اللَّهُمَّ أَخْرِجْ حُبَّ الدُّنْیا مِنْ قُلُوبِنَا»","بخش دوم\nمتن:\nحَتَّى إِذَا أَنِسَ نَافِرُهَا وَ اطْمَأَنَّ نَاكِرُهَا قَمَصَتْ بِأَرْجُلِهَا وَ قَنَصَتْ بِأَحْبُلِهَا وَ أَقْصَدَتْ بِأَسْهُمِهَا وَ أَعْلَقَتِ الْمَرْءَ أَوْهَاقَ الْمَنِيَّةِ قَائِدَةً لَهُ إِلَى ضَنْكِ الْمَضْجَعِ وَ وَحْشَةِ الْمَرْجِعِ وَ مُعَايَنَةِ الْمَحَلِّ وَ ثَوَابِ الْعَمَلِ. وَ كَذَلِكَ الْخَلَفُ بِعَقْبِ السَّلَفِ، لَا تُقْلِعُ الْمَنِيَّةُ اخْتِرَاماً وَ لَا يَرْعَوِي الْبَاقُونَ اجْتِرَاماً، يَحْتَذُونَ مِثَالًا وَ يَمْضُونَ أَرْسَالًا إِلَى غَايَةِ الِانْتِهَاءِ وَ صَيُّورِ الْفَنَاءِ.\nبعد الموت، البعث \nحَتَّى إِذَا تَصَرَّمَتِ الْأُمُورُ وَ تَقَضَّتِ الدُّهُورُ وَ أَزِفَ النُّشُورُ، أَخْرَجَهُمْ مِنْ ضَرَائِحِ الْقُبُورِ وَ أَوْكَارِ الطُّيُورِ وَ أَوْجِرَةِ السِّبَاعِ وَ مَطَارِحِ الْمَهَالِكِ سِرَاعاً إِلَى أَمْرِهِ مُهْطِعِينَ إِلَى مَعَادِهِ رَعِيلًا صُمُوتاً قِيَاماً صُفُوفاً، يَنْفُذُهُمُ الْبَصَرُ وَ يُسْمِعُهُمُ الدَّاعِي، عَلَيْهِمْ لَبُوسُ الِاسْتِكَانَةِ وَ ضَرَعُ الِاسْتِسْلَامِ وَ الذِّلَّةِ، قَدْ ضَلَّتِ الْحِيَلُ وَ انْقَطَعَ الْأَمَلُ، وَ هَوَتِ الْأَفْئِدَةُ كَاظِمَةً وَ خَشَعَتِ الْأَصْوَاتُ مُهَيْنِمَةً، وَ أَلْجَمَ الْعَرَقُ وَ عَظُمَ الشَّفَقُ وَ أُرْعِدَتِ الْأَسْمَاعُ لِزَبْرَةِ الدَّاعِي إِلَى فَصْلِ الْخِطَابِ وَ مُقَايَضَةِ الْجَزَاءِ وَ نَكَالِ الْعِقَابِ وَ نَوَالِ الثَّوَابِ.\nترجمه:\nبه گونه اى که افرادِ گريزان، به آن انس مى گيرند و منکرانش به آن دل مى بندند، ولى ناگهان همانند اسبى چموش که غافلگيرانه، پاهاى خود را بلند مى کند و سوار را بر زمين مى کوبد، دنيا آنها را به زمين مى زند! و با دام هاى خود آنها را گرفتار مى سازد! و تيرهاى خود را به سوى آنها پرتاب مى کند!\n(آرى) دنيا ريسمان مرگ را بر گلوى او مى افکند و کشان کشان به سوى گورى تنگ و جايگاهى وحشتناک مى برد! جايى که محلّ خويش را در بهشت و دوزخ مى بيند و پاداش اعمال خود را مشاهده مى کند و اين گونه پيوسته نسل هاى بعد به دنبال پيشينيان در حرکتند; نه مرگ از تباه کردن آن ها دست برمى دارد و نه بازماندگان (از سرنوشت پيشينيان عبرت مى گيرند و) از گناه و عصيان روى گردان مى شوند! همچون آنان عمل مى کنند و همانندشان گام برمى دارند، تا به پايان جهان برسند و در مسير فنا قرار گيرند.\nاوضاع اين جهان ناپايدار، همچنان ادامه مى يابد و زمانها پشت سر هم، سپرى مى شود و رستاخيز نزديک مى گردد، در اين هنگام آنها (انسانها) را از شکاف قبرها و آشيانه هاى پرندگان و لانه هاى درندگان و ميدان هاى هلاکت خارج مى سازند و با شتاب بسوى فرمان (و دادگاه) پروردگار حرکت مى کنند، در حالى که گردن کشيده اند (و نگران سرنوشت خويشند و هنگامى که در دادگاه الهى حضور مى يابند) به صورت گروههاى خاموش، صف به صف ايستاده، به گونه اى که چشم بخوبى آنها را مى بيند و صداى دعوت کننده (الهى) به آنها مى رسد; لباس نياز و مسکنت و تسليم و خضوع، بر تن پوشيده اند.\nراههاى چاره بسته شده و اميد و آرزو قطع گرديده است. قلبها از کار افتاده و نفس ها در سينه حبس شده و صداها بسيار ضعيف و کوتاه است. عرق، لجام بر دهان ها زده و وحشتى عظيم، همه را فراگرفته است. گوشها از صداى رعدآساى دعوت کننده بسوى حسابرسىِ پروردگار، به لرزه درآيد، و همه بايد نتيجه اعمال خود را دريابند: مجازات و کيفر الهى، يا نعمت و ثواب را.\nتفسیر:\nخطبه‌الغراء\nدر جلسهٔ گذشته حضرت دربارهٔ توحید و نبوت سخن گفتند و سپس از اهمیت تقوا گفتند؛ این‌که چرا انسان باید متقی باشد؛ و بعد هم دربارهٔ دنیا صحبت می‌کنند. شاید ازاین‌جهت که یکی از مهم‌ترین عواملی که انسان را از تقوا دور می‌کند، همین دنیازدگی است.\nپس حضرت دنیا را برای ما توضیح می‌دهد.\nبدانید دنیا جایی است که آبشخورش کدر است، آب گوارایی ندارد، و سرابی متعفن است. رسیدن به آن هم خودش آلودگی می‌آورد.\nمنظرهٔ دنیا آدم را شگفت‌زده می‌کند؛ اما باطنش بد است، هلاک‌کننده و کشنده است.\nدنیا چند ویژگی دارد:\nسرتاسر دنیا فریب و دروغ است؛ قابل‌اعتماد نیست؛ زودگذر است؛ پلی است برای رسیدن به جایی دیگر؛ فریبی است متغیر که هر روز رنگ عوض می‌کند. زیبایی دارد، اما زیبایی‌اش اندک و رو به افول است. سایه‌ای زودگذر دارد. ستونش کج شده و در حال فروریختن است؛ انسان عاقل به ستون کج تکیه نمی‌دهد.\nدر مقابل دنیاطلبان، عده‌ای هم هستند که زودگذر بودن دنیا و این‌که دنیا جای فریب است را فهمیده‌اند و با دنیا مبارزه کرده‌اند؛ اما باز هم از فریب دنیا در امان نیستند.\n♦️ «حَتَّی إِذَا آنَسَ نَافِرُهَا وَاطْمَأَنَّ نَاکرُهَا»\nدنیا آن‌قدر دنبال انسان می‌رود تا این‌که کسی که تا دیروز از دنیا متنفر [نافر] بود، امروز با دنیا انس می‌گیرد.\nکسی که تا دیروز منکر دنیا بود، به دنیا تکیه می‌زند و مطمئن می‌شود. [اطمأنَّ] گاهی انسان یک‌عمر دنیا را ترک کرده، اما در اواخر عمر دلبستهٔ دنیا می‌شود.\nکسانی که از اول به دنیا دل داده‌اند و گروهی که از دنیا متنفر بوده‌اند هم از فریب دنیا در امان نیستند.\nممکن است بلغزند و با دنیا مأنوس شوند.\nهر دو گروه - چه دنیاطلب و چه کسانی که دنیا را طلاق داده‌اند - می‌توانند اسیر دنیا شوند.\nدنیا با آنان چه می‌کند؟!\n♦️ «قَمَصَتْ بِأَرْجُلِهَا»\nدنیا سه بلا سر آنان می‌آورد.\n۱- اسب وقتی می‌خواهد سوار خود را بیندازد، پاها را روی زمین می‌کوبد و دست‌هایش را بلند می‌کند و سوارکار را از پشت به زمین می‌زند.\nدنیا هم همین‌گونه است: وقتی کسی سوار بر دنیا شد و به دنیا رسید، همان لحظه‌ای که فکر می‌کند وقت لذت‌بردن است، دنیا دست‌ها را بالا می‌برد و پاها را بر زمین می‌کوبد و سوار را محکم به زمین می‌زند و استخوان‌هایش را خرد می‌کند. [قَمَصَتْ]\n♦️ «وَقَنَصَتْ بِأَحْبُلِهَا»\n۲- دنیا عاشقان و دنیاطلبان را شکار می‌کند. [قَنَصَتْ] همه‌جا دام پهن کرده [أَحْبُل] تا انسان را در دام خودش گرفتار کند؛ دنیا طالبان خودش را به زمین می‌زند.\n♦️ «وَاقْصَدَتْ بِأَسْهُمِهَا»\n۳- دنیا عاشق خودش را با تیرهای تیز [أَسْهُم] نشانه می‌گیرد.\nاگر کسی بخواهد از گُردهٔ دنیا سواری بگیرد، زمین می‌افتد.\nدنیا برای او دام پهن کرده تا او را بگیرد.\nدنیا با تیرهای تیز او را نشانه گرفته که قطعاً به هدف هم می‌خورد.\nکلام حضرت این است: اگر سمت دنیا بروید، شما را طرد می‌کند؛ و اگر دل از دنیا ببُرید، خودش را در اختیار شما قرار می‌دهد. اگر بخواهید با دنیا خوش باشید، دنیا روی خوش‌نشان نمی‌دهد و پس می‌زند.\n♦️ «وَأَعْلَقَتِ الْمَرْءَ أَوْهَاقَ الْمَنِیةِ»\nدنیا آن‌چنان گرفتار و اذیت می‌کند و سرانجام طناب دار [أَوْهَاق] را به گردن دنیاطلب می‌اندازد. [أَعْلَقَتْ] و مرگ فرامی‌رسد.\nدنیایی که تا دیروز او را فریب می‌داد و با دعوت جلبش می‌کرد، امروز با دست خودش عاشقان را به وادی مرگ تحویل می‌دهد.\n♦️ «قَائِدَةً لَهُ إِلَی ضَنْک الْمَضْجَعِ»\nدنیا بعد از مرگ هم رها نمی‌کند؛ حتی او را یک روز هم نگه نمی‌دارد.\nدنیا مرده را به سمت قبر تنگ [ضَنْک] سوق می‌دهد؛ تازه فشارها و حساب‌وکتاب شروع می‌شود.\n♦️ «وَوَحْشَةِ الْمَرْجِعِ»\nاو را به جایگاه وحشت و ترس بازمی‌گرداند. دنیاطلب می‌ماند و وحشتِ داخل قبر.\n♦️ «وَمُعَاینَةِ الْمَحَلِّ وَثَوَابِ الْعَمَلِ»\nاو می‌ماند و دیدنِ جایگاهی که پرده‌ها از مقابل دیدگان کنار رفته است.\nقبر هرکس، باغی از باغ‌های بهشت یا حفره‌ای از حفره‌های جهنم است. چشم وسعت دید پیدا می‌کند؛ جایگاه خودش را در برزخ - بهشت یا جهنم - می‌بیند.\nعده‌ای هم که کار خوب و ثواب داشته‌اند، ثواب عمل را می‌بینند؛ و هم بدی و عذاب را؛ یعنی نتیجهٔ هر دو طرف را می‌بینند.\nدر قبر، مشاهده‌کردن مطرح است؛ عمل در کار نیست؛ همه چیز دیده می‌شود.\n♦️ «وَکذَلِک الْخَلَفُ یعْقُبُ السَّلَفَ»\nآیندگان دنباله‌رو گذشتگان‌اند.\nبزرگ‌ترین آفت، فراموشی است؛ جمله‌های تلخی است که همه تجربه کرده‌ایم و بعد فراموشش کرده‌ایم.\nاین ماجرا همچنان ادامه دارد: فرزندان و نوادگان به دنیا می‌آیند، دل به دنیا می‌دهند، قیامت را فراموش می‌کنند، مرگ آن‌ها را فرامی‌گیرد و عذاب قبر شروع می‌شود.\n♦️ «لَا تَقْلِعُ الْمَنِیةُ اخْتِرَامًا»\nنه مرگ از نابودکردن آن‌ها بازمی‌ایستد. [لَا تَقْلِعُ] مرگ از بردن آن‌ها دست برنمی‌کشد. مرگ ناگهانی [اخْتِرَامًا] در کمین نشسته؛ جوان و پیر هم نمی‌شناسد.\nچرا عبرت از گذشتگان نمی‌گیرید؟ ببینید چند نسل از شما زیر خاک‌اند. بدانید مرگ دست از سر نسل‌های آینده هم برنمی‌دارد. این قانون الهی است که مرگ برای همه است.\n♦️ «وَلَا یرْعَوِی الْبَاقُونَ إِجْتِرَامًا»\nو نه دنیاطلبان از جرم و گناه و خطا دست می‌کشند. [لَا یرْعَوِی]\nنه مرگ دست از سر آنان برمی‌دارد، نه آنان دست از خطا می‌کشند. همان رویهٔ غلط پدران خود را ادامه می‌دهند تا مرگ فرابرسد.\n♦️ «یحْتَذُونَ مِثَالًا»\nمثل گذشتگان و اجداد خود قدم برمی‌دارند. [یحْتَذُونَ] در هر گناهی که پدرانشان فرورفته‌اند، همان راه را می‌روند.\n♦️ «وَیمْضُونَ إِرْسَالًا إِلَی غَایةِ الِانْتِهَاءِ»\nمثل گلهٔ گوسفند که فهم ندارد؛ هر جا پیش‌گامشان حرکت کرد، آن‌ها پشت سر او راه می‌افتند. دنباله‌رو گذشتگان‌اند تا این جهان و عمرشان به پایان برسد. [غَایةِ الِانْتِهَاءِ]\nکسانی که چشم‌بسته راه خطای گذشتگان را می‌روند، به گلهٔ گوسفندان تشبیه شده‌اند.\n♦️ «وَصَیرِ الْفَنَاءِ»\nو سرانجام به فنا و نابودی جسم برسند.\nدنباله‌رو گذشتگان‌اند، اما عبرت نمی‌گیرند.\nدیدیم دیگران مبتلا و گرفتار شدند؛ ما هم یک روز می‌رویم و فراموش می‌شویم؛ گویی اصلاً وجود نداشتیم.\nآنچه مهم است عبرت است؛ اما عبرت‌گرفتن هم فراموش می‌شود.\n♦️ «حَتَّی إِذَا تَصَرَّمَتِ الْأُمُورُ»\nدنیا همچنان جلو می‌رود. امور دنیا - شغل، حکومت، موقعیت، پول، پست و مقام - مدام دست‌به‌دست می‌شود و داستان دنیا ادامه دارد.\n♦️ «وَتَقَضَّتِ الدُّهُورُ وَأَزِفَ النُّشُورُ»\nروزگار سپری می‌شود و عمر به پایان می‌رسد.\nرستاخیز نزدیک می‌شود. [أَزِفَ]\nجملات بعد، حضرت از قیامت و حساب‌وکتاب می‌گوید:\n♦️ «أَخْرَجَهُمْ مِنْ ضَرَائِحِ الْقُبُورِ»\nمیت روزی از گودال [ضَرَائِح] قبر بیرون کشیده می‌شود.\n♦️ «وَأَوْکارِ الطُّیورِ وَأَوْجِرَةِ السِّبَاعِ»\nمیت را از لانه [أَوْکار] پرندگان بیرون می‌آورند. بعضی در بیابان مرده‌اند و خوراک طیور شده‌اند؛ گوشت و جسمشان را از لانهٔ پرنده بیرون می‌کشند.\nمیت را از آشیانه [أَوْجِرَة] درندگان بیرون می‌آورند؛ جسمی را که خوراک وحوش شده، از آشیانهٔ وحوش بیرون می‌کشند.\n♦️ «وَمَطَارِحِ الْمَهَالِک»\nعده‌ای در میدان [مَطَارِح] مرگ افتاده‌اند: چه میدان جنگ، چه بیمارستان، چه خیابان؛ هر کس هر جاافتاده باشد، او را برای قیامت از خاک بلند می‌کنند.\n«وَمَا تَدْرِی نَفْسٌ مَاذَا تَکسِبُ غَدًا وَمَا تَدْرِی بِأَی أَرْضٍ تَمُوتُ. لُقْمَانُ - ۳۴»\nو هیچ‌کس نمی‌داند کجا و با چه حالتی می‌میرد. یکی از نعمت‌ها این است که نمی‌دانید چگونه و کجا می‌میرید؛ و اگر می‌دانستید، زندگی بر شما تلخ می‌شد.\n♦️ «سِرَاعًا إِلَی أَمْرِهِ مُهْطِعِینَ إِلَی مَعَادِهِ»\nپیکرها سریع به سمت دادگاه الهی حرکت می‌کنند.\nبا شتاب حرکت می‌کنند [مُهْطِعِینَ] به سمت معاد و جایگاهی که خداداده است.\n♦️ «رَعِیلًا صُمُوتًا قِیامًا صُفُوفًا»\nجمعی [رَعِیلًا] ساکت‌اند؛ مهر سکوت به دهان دارند؛ یا نمی‌گذارند، یا از ترس نمی‌توانند حرف بزنند.\nهمه در صف‌های طولانی، پشت‌سرهم ایستاده‌اند.\n♦️ «ینْقُذُهُمُ الْبَصَرُ»\nویژگی قیامت این است: هرکسی نگاه کند، تا انتهای صف طولانی را می‌بیند.\nدر قیامت، بصر انسان قدرت پیدا می‌کند: همه را می‌بیند، می‌شناسد، و نتیجهٔ کار را می‌فهمد.\n«مُتَّکئِینَ عَلَیهَا مُتَقَابِلِینَ وَاقِعَةٌ. - ۱۳»\nاهل بهشت بر تخت‌هایی تکیه زده‌اند؛ همه باوجود فاصله، روبه‌روی هم هستند. در قیامت محدودیت دنیایی نیست؛ در عین فاصله، همه چیز را می‌بیند و می‌شنود.\n♦️ «وَیسْمَعُهُمُ الدَّاعِی»\nوقتی فرشتهٔ مخصوص حسابرسی صدا بلند می‌کند، همه به طور کامل و یکسان صدای او را می‌شنوند.\n♦️ «عَلَیهِمْ لَبُوسُ الِاسْتِکانَةِ وَضَرَعُ الِاسْتِسْلَامِ وَالذِّلَّةِ»\nکسانی که عشق دنیایی داشته‌اند، لباس فروتنی [الِاسْتِکانَةِ] بر تنشان می‌کنند.\nدنیا محل گردن‌کلفتی، امتیازخواهی، تکریم و احترام اجباری بود؛ اما آنجا لباس ضعف [ضَرَعُ] و تسلیم و ذلت بر تن آنان می‌کنند. همه بنده‌اند؛ قدرت فقط از آنِ خداست که مالک یوم‌الدین است.\n♦️ «قَدْ ضَلَّتِ الْحِیلُ وَانْقَطَعَ الْأَمَلُ»\nجایی است که راه فریب و نیرنگ بسته است؛ چاره [الْحِیلُ] تمام شده.\nآرزوها و خواسته‌ها قطع می‌شود.\n♦️ «وَهَوَتِ الْأَفْئِدَةُ کاظِمَةً وَخَشَعَتِ الْأَصْوَاتُ مُهَینِمَةً»\nجایی است که نفس در سینه حبس می‌شود [هَوَتِ] و دل‌ها به سکوت می‌افتد،\nو صداها آهسته [مُهَینِمَةً] و آرام می‌شود.\n♦️ «وَأَلْجَمَ الْعَرَقُ وَعَظُمَ الشَّفَقُ»\nصورت‌ها انگار لجامِ عرق خورده‌اند؛ مثل اسبِ لجام‌زده.\nاین بندهٔ خدا از ترس و اضطراب عرق می‌ریزد و ترس به اوج خودش رسیده است.\n♦️ «وَأَرْعَدَتِ الْأَسْمَاعُ لِزَبْرَةِ الدَّاعِی إِلَی فَصْلِ الْخِطَابِ»\nگوش‌های همهٔ اهل قیامت از شدت صدا به لرزه [أَرْعَدَتْ] می‌افتد. چرا این لرزش و اضطراب؟\nبه‌خاطر فریاد و صدای بلند [لِزَبْرَةِ] فرشته‌ای است که ندا می‌دهد برای حسابرسی و حرکت به‌سوی فصل‌الخطاب. تمام وجود می‌لرزد.\nمثل دنیا نیست که آرزو کنند و از کسی چیزی طلب کنند؛ راه حیله و آرزو بسته است.\n♦️ «وَمُقَایضَةُ الْجَزَاءِ»\nدنیا جای عمل است و آخرت جای حساب.\nبده‌وبستان آخرت این‌گونه است: مبادله [مُقَایضَةُ] می‌کنند؛ اعمال را می‌گیرند و به اندازهٔ عمل، ثواب و به‌ازای هر عمل، جزا می‌دهند.\n♦️ «وَنَکالِ الْعِقَابِ وَنَوَالِ الثَّوَابِ»\nدر برابر عمل، مجازات می‌دهند و در ازای آن، بخشش [نَوَالِ].\nمثل صرافی، آخرت جای مبادله و معاوضه است. گاهی عمل خوب را مبادله می‌کنند با همنشینیِ امیرالمؤمنین.\nبهشت جای معاوضه است و هر کس در گرو اعمال خویش است.\nابتدا حضرت دنیا را ترسیم می‌کند و سپس سرزنش می‌کند که حواستان باشد و غافل نباشید،\nاللهم اجعل عواقب امورنا خیرا","بخش سوم\nمتن:\nتنبيه الخلق‏:\nعِبَادٌ مَخْلُوقُونَ اقْتِدَاراً وَ مَرْبُوبُونَ اقْتِسَاراً وَ مَقْبُوضُونَ احْتِضَاراً وَ [مُضَمِّنُونَ‏] مُضَمَّنُونَ أَجْدَاثاً وَ كَائِنُونَ رُفَاتاً وَ مَبْعُوثُونَ أَفْرَاداً وَ مَدِينُونَ جَزَاءً وَ مُمَيَّزُونَ حِسَاباً؛ قَدْ أُمْهِلُوا فِي طَلَبِ الْمَخْرَجِ وَ هُدُوا سَبِيلَ الْمَنْهَجِ وَ عُمِّرُوا مَهَلَ الْمُسْتَعْتِبِ وَ كُشِفَتْ عَنْهُمْ سُدَفُ الرِّيَبِ وَ خُلُّوا لِمِضْمَارِ الْجِيَادِ وَ رَوِيَّةِ الِارْتِيَادِ وَ أَنَاةِ الْمُقْتَبِسِ الْمُرْتَادِ فِي مُدَّةِ الْأَجَلِ وَ مُضْطَرَبِ الْمَهَلِ‏.\nفضل التذكير:\nفَيَا لَهَا أَمْثَالًا صَائِبَةً وَ مَوَاعِظَ شَافِيَةً لَوْ صَادَفَتْ قُلُوباً زَاكِيَةً وَ أَسْمَاعاً وَاعِيَةً وَ آرَاءً عَازِمَةً وَ أَلْبَاباً حَازِمَةً؛ فَاتَّقُوا اللَّهَ تَقِيَّةَ مَنْ سَمِعَ فَخَشَعَ وَ اقْتَرَفَ فَاعْتَرَفَ وَ وَجِلَ فَعَمِلَ وَ حَاذَرَ فَبَادَرَ وَ أَيْقَنَ فَأَحْسَنَ وَ عُبِّرَ فَاعْتَبَرَ وَ حُذِّرَ فَحَذِرَ وَ زُجِرَ فَازْدَجَرَ وَ أَجَابَ فَأَنَابَ وَ رَاجَعَ فَتَابَ وَ اقْتَدَى فَاحْتَذَى وَ أُرِيَ فَرَأَى؛ فَأَسْرَعَ طَالِباً وَ نَجَا هَارِباً فَأَفَادَ ذَخِيرَةً وَ أَطَابَ سَرِيرَةً وَ عَمَّرَ مَعَاداً وَ اسْتَظْهَرَ زَاداً لِيَوْمِ رَحِيلِهِ وَ وَجْهِ سَبِيلِهِ وَ حَالِ حَاجَتِهِ وَ مَوْطِنِ فَاقَتِهِ وَ قَدَّمَ أَمَامَهُ لِدَارِ مُقَامِهِ؛ فَاتَّقُوا اللَّهَ عِبَادَ اللَّهِ جِهَةَ مَا خَلَقَكُمْ لَهُ وَ احْذَرُوا مِنْهُ كُنْهَ مَا حَذَّرَكُمْ مِنْ نَفْسِهِ وَ اسْتَحِقُّوا مِنْهُ مَا أَعَدَّ لَكُمْ بِالتَّنَجُّزِ لِصِدْقِ مِيعَادِهِ وَ الْحَذَرِ مِنْ هَوْلِ مَعَادِهِ.\nترجمه:\nآنها بندگانى هستند که با قدرتِ (الهى) آفريده شده اند و بى اراده خويش پرورش داده مى شوند و براى حضور در پيشگاهِ خدا، قبض روح مى گردند وبه قبرها سپرده مى شوند و (سرانجام) به استخوان هاى پوسيده اى مبدّل خواهند شد و (سپس) تک و تنها برانگيخته مى شوند و (در برابر اعمالشان) جزا داده خواهند شد;\nحساب هر يک، از ديگرى جداست (ولى به لطف الهى در اين دنيا) به آنها مهلت کافى براى جستجوى طُرُق خروج از مشکلات و مسئوليّت ها داده شده، راه وصول به سعادت به آنها ارائه شده است; زمان کافى براى جلب رضايت پروردگار، در اختيار دارند، پرده هاى تاريک شک و ترديدها (با ارائه دلائل روشن از سوى پروردگار) از مقابل آنها کنار رفته و ميدان، براى تمرين و آمادگى آنها و انديشه بهتر و کسب آرامش (در طريق جستجوىِ حقيقت) در مدّت زندگى و دوران تلاش، باز گذارده شده است.\nوه! چه مَثَل هاى صائب و رسايى، و چه اندرزهاى شفابخشى، به شرط آن که با قلب هاى پاک و گوش هاى شنوا و اراده هاى قاطع و عقل هاى دورانديش روبرو شود.\nپس تقواى الهى پيشه کنيد! تقواى کسى که چون (اوامر و نواهى الهى را) بشنود خضوع کند (و در برابر آن) تسليم شود، و چون گناه کند (عذر تقصير به پيشگاه خدا آورد و) اعتراف کند (و در مقام توبه برآيد) و چون خاشع گردد (به وظايف خود) عمل کند، و چون بيمناک شود به اطاعت حق مبادرت نمايد، و چون (به مرگ و لقاى پروردگار) يقين کند، نيکى نمايد، و هرگاه درس عبرت به او دهند، عبرت پذيرد، و هر زمان او را (از اعمال خلاف) بر حذر دارند، حذر کند، و اگر (از نافرمانى خدا) منعش کنند، باز ايستد، و آنگاه که (به زبان) اجابت (دعوت حق) کند (در عمل) به سوى او باز گردد و چون باز گردد، توبه کند، و چون تصميم به پيروى (از پيشوايان دين) گيرد، به دنبال آنها گام بردارد، و چون (حقايق را) به او نشان دهند (چشم باز کند و) ببيند.\nکسى که با سرعت در طلب حق، حرکت کند و از نافرمانى ها بگريزيد، در نتيجه از اين راه ذخيره اى به دست آورد و باطن خويش را پاکيزه کند و آخرت خود را آباد سازد و توشه اى براى روز حرکت به سوى مقصد و هنگام حاجت و منزلگاه نياز با خود بردارد و پيشاپيشِ خود به سراى جاودانيش بفرستد. پس تقواى الهى پيشه کنيد اى بندگان خدا! در راستاى هدفى که شما را براى آن آفريده. و از مخالفت فرمانش بر حذر باشيد! آنچنان که به شما هشدار داده و بدين وسيله استحقاق آنچه را به شما وعده داده است، پيدا کنيد که وعده او صادق و قطعى است! و به اين طريق، از وحشت روز رستاخيز در امان بمانيد.\nتفسیر:\n   خطبه‌الغرّاء\n«عِبَادٌ مَخْلُوقُونَ اقْتِدَارًا وَ مَرْبُوبُونَ اقْتِسَارًا»\nبعد از بیان ویژگی‌های دنیا، مجدداً به توصیهٔ تقوا پرداخته شده است؛ اینکه جمعیت انبوه و بندگان خدا در هر گروه و طیفی که هستند، باقدرت و اقتدار خدای متعال خلق شده‌اند، بدون اینکه اراده و غلبه‌ای داشته باشند. در واقع، بدون اینکه بخواهند، در مسیر دنیا قرار داده شده‌اند. (به‌دنیاآمدن انسان‌ها از قسم جبر است.) خداوند باقدرت خود، مخلوق را خلق کرده و در مسیر تکامل طبیعی قرار داده است.\nاختیار در اصل حرکت نیست، اما در چگونگیِ زندگی‌کردن، اختیار با افراد است که خود انتخاب می‌کنند؛ ولی اینکه کسی بخواهد جوان بماند، نمیرد یا پیر نشود، امری اجباری است. شرایط پیری را نمی‌توان دفع کرد، زیرا انسان به جبر قرار داده شده است.\n«وَ مَقْبُوضُونَ احْتِسَابًا»\nسرانجام عمر، قبض روح می‌شود درحالی‌که آنجا حضور دارند. حضور میت در بارگاه خدای متعال، حضور ملائک موکل و حضور ملک‌الموت؛ پرده‌ها از مقابل چشم افتاده است و او حضور را می‌بیند. هیچ‌کس نمی‌تواند از این اجبار شانه خالی کند. کیفیت زندگی به دست بشر است، ولی ممات (مرگ) به دست خداست.\n«وَ مُضَمَّتُونَ أَجْدَاثًا وَ کائِنُونَ رُفَاتًا»\nمرگ که حاصل شد، انسان در قبر گذاشته می‌شود و بعد از مدتی متلاشی می‌گردد؛ استخوان‌ها پوسیده و خرد شده‌اند [رُفَاتًا].\n«وَ مَبْعُوثُونَ أَفْرَادًا وَ مَدِینُونَ جَزَاءً وَ مُمَیزُونَ حِسَابًا»\nروح هر شخص به‌صورت تنها و فردی مبعوث می‌شود، و هر کدام جزا و پاداش متناسب با اعمال خود را دریافت می‌کند [مَدِینُونَ]، و حساب هرکدام از دیگری متمایز می‌گردد. حساب هر فرد با دیگر افراد متفاوت است.\n«وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَیٰ»\nبار کسی به دوش دیگری حمل نمی‌شود؛ افراد، بارکشِ عمل خود هستند.\nآنچه که در اختیار انسان گذاردند و مورد سؤال نیز قرار می‌گیرد، چیست؟!\n«قَدْ أُمْهِلُوا فِی طَلَبِ الْمَخْرَجِ وَ هُدُوا سَبِیلَ الْمَنْهَجِ»\nبه آن‌ها مهلت داده شده بود تا راه‌های خروج از جهنم را طلب کنند. فرصت داده شد [أُمهِلُوا] تا تلاش کنند که گرفتار آتش نشوند. عمر، فرصتی بود تا سبیل هدایت [مَنْهَج] را پیدا کنند؛ اینکه راه درست را بیابند و از آن تبعیت کنند تا عمر به جهل و بطالت نگذرد. بهانهٔ نبودن وقت، ناتوانی یا بلد نبودن، هیچ عذری را مورد پذیرش قرار نمی‌دهد.\n«وَ عُمِّرُوا مَهَلَ الْمُسْتَعْتِبِ»\nعمر و همهٔ فرصت‌ها داده شده بود تا طلب رضایت [مُسْتَعْتِب]، یعنی رضایت خالق را نمایند و رضایت خلق را جلب کنند. اگر به دنبال این طلب نرفتند، هیچ عذری پذیرفته نیست.\n«وَ کشِفَتْ هُمْ سُدَفُ الرِّیبِ»\nمهلت، فرصتی برای کشف نور حقیقت بود تا در میان ظلمت، شک، وهم و خیال نمانند. اگر در جهل ماندند، پذیرفته نیست؛ چرا که هم‌سن‌وسالان از ظلمت جدا شده و به نور حقیقت دست یافتند. پس مشکل از خدا و عمر نبوده، بلکه اشکال از هدف بوده است؛ باید عمر را از شک و جهل [سُدَفُ الرِّیبِ] به سمت یقین بالا می‌کشید. شک همیشه با دل‌نگرانی و کدورت همراه است، اما با یقین می‌توان به آن نورِ طلب شده رسید.\n«وَ خُلُّوا لِمِضْمَارِ الْجِیادِ وَ رَوِیةَ الِارْتِیادِ»\nدر دنیا برای شما زمان را خالی و رها کرده بودند [خُلُّوا] تا در این مسابقه [مِضْمَار] پیشی بگیرید. مسابقهٔ فهم، عمل و تقواست؛ اگر جلو نزدید، خودتان مقصر هستید و نباید تقصیر را به گردن دیگری انداخت. به شما فرصت داده شد تا تفکر و اندیشهٔ [رَوِیة] صحیح را پیدا کنید. مضمار الجیاد، مسابقهٔ اسب‌سواری است که در آن اسب برای تمرینات، تغذیه و ورزش بر اساس یک حساب‌وکتاب تنظیم می‌شود تا برای روز مسابقه آماده باشد.\n«وَ أَنَاهُ الْمُقْتَبَسُ الْمُرْتَادُ»\nتا با صبر و بردباری [أَنَاهُ]، نور را کسب کنید. کسب نور با خواندن چند جلد کتاب نیست، بلکه در گرو اخلاص و زهد است. آنچه در قیامت خریدار دارد، نورانیت است، نه خواندن چندین جلد کتاب.\n«فِی مُدَّةِ الْأَجَلِ»\nدر مدت کوتاه زندگی که زمان کافی برای کسب نور داشتید. خداوند هرگز به کاری که نشدنی باشد، امر نمی‌کند؛ اگر به تقوا امر کرده، یعنی امکانات و فرصت‌های آن فراهم است. هر کس در هر شرایطی که دارد (صحت و سلامت، فقر و غنا) باید متقی باشد؛ چرا که تقوای هر فرد متناسب با شرایط اوست.\n«وَ مُضْطَرَبِ الْمَهَلِ»\nدر رفت‌وآمدِ [مُضْطَرَب] مهلت و فرصت‌ها (روزی خوشی و تلخی، کم‌وزیاد، جوانی و پیری)، انتظار می‌رفت که انسان اندیشه، یقین، نور و فضایل را کسب کند.\n«فَیا لَهَا أَمْثَالًا صَائِبَةً وَ مَوَاعِظَ شَافِیةً»\nجای تعجب است! مثال‌هایی که رسا و آشکار [صَائِبَة] هستند و موعظه‌هایی که شفادهنده هستند، اما به‌واسطهٔ آن‌ها راه را پیدا نکردند. مخاطب با مثال‌های محسوس متوجه می‌شود؛ خداوند به گفتن کلیات و فطرت اکتفا نکرد و کتاب آسمانی را چنان بیان کرد که همه آن را بفهمند. برای مثال، قیامت را بیان کرد، اما باز عده‌ای نفهمیدند. چقدر شگفت‌انگیز است این موعظه‌های شفابخش! شفا گاهی در تربت، گاهی در دگر و گاهی در موعظه است؛ بیماری روح و بیداری آن در گرو موعظه است. چرا وقتی کلمات حضرت شنیده می‌شود، مورد تأثیر قرار نمی‌گیرد؟! علت تأثیرگذار نبودن قرآن و موعظه در برخی اشخاص چیست؟!\n«لَوْ صَادَفَتْ قُلُوبًا زَاکیةً وَ أَسْمَاعًا وَاعِیةً»\nمثال‌ها شفابخش هستند، به شرطی که با قلوب پاک [زَاکیة] برخورد کنند. اگر قلب طاهر نباشد، آمادگی برای دریافت موعظهٔ پاک نیست. اگر ظرف وجود آلوده باشد و آب گوارا در ظرفی نجس ریخته شود، نجس می‌شود؛ و قلبِ گرفتار در هوی‌وهوس، پذیرای حقیقت نیست. سخنی که شنیده می‌شود باید با عمق جان درگیر باشد [أَسْمَاعًا وَاعِیةً].\n«وَ إِرَاءً عَازِمَةً وَ أَلْبَابًا حَازِمَةً»\nنصیحت به شرطی اثر می‌کند که اراده‌ای جزم و عقلی دوراندیش [حَازِمَة] وجود داشته باشد. گاهی عقل شنیده‌ها را می‌فهمد، اما به دلیل نبودِ حال‌وحوصله، اراده‌ای جزم نمی‌شود و عمل به فردا واگذار می‌گردد. تنها زمانی که عزم جزم و عقل دوراندیش باشد، موجود موعظه پذیر می‌شود.\n«فَاتَّقُوا اللَّهَ تَقِیةً مَنْ سَمِعَ فَخَشَعَ وَاقْتَرَفَ فَاعْتَرَفَ»\nبندگان خدا، تقواپیشه باشید. تقوا به ادعا و حرف نیست؛ تقوا یعنی وقتی حرف خدا شنیده شد [مَنْ سَمِعَ]، در برابر آن خشوع کرد. تقوا یعنی اگر گناهی مرتکب شد [اقْتَرَفَ]، به آن اعتراف و عذرخواهی کند. تقوا یعنی اگر گناهی سر زد، بداند که خدا او را زیر نظر دارد.\n«وَ وَجِلَ فَعَمِلَ وَ حَاذَرَ فَأَبَادَرَ»\nاگر از جهنم ترسی به سراغ آمد که از توان آدمی خارج است، در آن ترس باید به قیامِ عمل مبادرت کرد. در مکتب تقوا، ترس منجر به عمل می‌شود، برخلاف مکتب دنیا که ترس سبب گوشه‌گیری و گوشه‌نشینی می‌گردد. کسی که از مطلبی بیمناک شد [حَاذَرَ]، در آن مبادرت به عمل می‌کند.\n«وَ أَیقَنَ فَأَحْسَنَ وَ عُبِّرَ فَاعْتَبَرَ»\nتقوا به معنای رسیدن به‌یقین است و با یقین، کارها به بهترین نحو انجام می‌شود. نشانهٔ ایمان و یقین، ترمزگرفتن در برابر خطاهاست. یکی از مراتب تقوا، عبرت‌آموزی است [فَاعْتَبَرَ]؛ یعنی با دیدن هر چیزی، عبرت بگیرد و بداند که روزی خود نیز با همان شرایط روبرو خواهد شد.\n«وَ حُذِّرَ فَحَذِرَ وَ زُجِرَ فَازْدَجَرَ»\nتقوا این است: هر آنچه به او هشدار داده شد [حُذِّرَ]، در ترک و نهی هم مطیع و خاشع باشد. امر به نهی شد خود را از آن باز بدارد.\n«وَ أَجَابَ فَأَنَابَ وَ رَاجَعَ فَتَابَ»\nتقوای کسانی که دعوت را اجابت می‌کنند و پای عمل هم خود را ثابت می‌کنند عبودیت دیگری ندارند [أَنَاب]. توبه به ادعا نیست، به برگشت از سهو و غفلت است.\n«فَاقْتَدَی فَاحْتَذَی وَ أُرِی فَرَآیا»\nاقتدا به امام کنید و پشت او قدم بردارید. (فرهنگ، مرام، و سبک امیرالمؤمنین می‌شود تقوا.) کار تقوا بجایی می‌رسد که اموری را به او نشان می‌دهند [أُرِی]، باطن امور را نشان می‌دهند.\n«فَأَسْرَعَ طَالِبَانُ وَ نَجَا هَارِبَانِ»\nکسی با این موارد گفته شده صاحب تقوا شود لاجرم برای رسیدن به مطلوب که رضایت الهی است، به‌سرعت حرکت می‌کند و نجات می‌یابد درحالی‌که از جهل، گناه، جهنم فراری‌ست [هَارِبَانِ].\n«فَأَفَادَ ذَخِیرَةً وَ أَطَابَ سَرِیرَةً وَ عَمَّرَ مَعَادًا»\nنتیجهٔ حرکت سریع به‌سوی امور: نور ذخیرهٔ قیامت می‌شود، کوله‌بار و توشه را سنگین می‌کند. باطن را پاک می‌کند [أَطَابَ] و معاد را آباد [عَمَّرَ] می‌کند.\n«وَ اسْتَظْهَرَ زَادًا لِیوْمِ رَحِیلِهِ»\nزاد و توشه مسیر آماده می‌کند برای روزی که کوچ می‌کند و قلب از حرکت می‌ایستد.\n«وَ وَجَّهَ سَبِیلَهُ وَ حَالَ حَاجَتِهِ وَ مَوْطِنَ فَاقَتِهِ»\nزاد و توشه برای روزی که حاجت قبر، برزخ و قیامت اوست. خرج امروز را ذخیرهٔ فردا می‌کند. برای منزلگاه نیاز [فاقَتِه] که با دست پر باشد.\n«وَ قَدَّمَ أَمَامَهُ لِدَارِ مُقَامِهِ»\nکارهای نیک را پیش می‌فرستد برای فردا روزی که دار مقام و ابدی هست.\n«فَاتَّقُوا اللَّهَ عِبَادَ اللَّهِ جَهَهَ مَا خَلَقَکمْ لَهُ»\nبندگان خدا تقوا داشته باشید، همان‌گونه که خدا هدف و برنامه را برای شما مشخص کرده [جَهَهَ مَا خَلَقَ] همان مسیری را بروید که خدا به‌خاطر همان خلق کرده. «وَ مَا خَلَقْتُ الْجِنَّ وَ الْإِنْسَ إِلَّا لِیعْبُدُونَ» تقوای جزئی در افراد متناسب با شرایط هر شخص است. در یک شخص تقوای چشم، در دیگری تقوای احترام، در فردی تقوای زبان، برای کسی تقوای انفاق، هرکدام تقوای خاصی دارند، در همان مسیری که خدا خواسته باید حرکت کنند.\n«وَ احْذَرُوا مِنْهُ کنْهَ مَا حَذَرَکمْ مِنْ نَفْسِهِ»\nبا تمام توان و قدرت بپرهیزید از آنچه که خدا از آن برحذر داشته [کنْهَ مَا حَذَرَ] با بیشترین حذر از رفتن به سمت خطا و پرهیز از شبهات، مطلق صرف‌نظر کنید.\n«وَ اسْتَحِقُّوا مِنْهُ مَا أَعَدَّ لَکمْ بِالتَّنَجُّزِ لِصِدْقِ مِیعَادِهِ»\nاگر انجام دهید مستحق آن وعده‌ای می‌شوید که خداداده. وعدهٔ نجات مؤمن، وعدهٔ بهشت، باید استحقاقی باشد، بن‌مایه داشته باشد. بهشت را به بها می‌دهند. باید مقداری از راه طی شده باشد. استحقاق ایجاد کنید تا خدا شمارا به وعده‌های داده شده برساند.\n«وَ الْحَذَرَ مِنْ هَوْلِ مَعَادِهِ»\nایجاد آمادگی کنید تا به وعده‌داده‌شده، هول و وحشت، اضطراب قیامت را بر شما وفا کند.\n✅ امنیت و آرامش و بهشت لازم دارید امور تقوا و سفارش‌شده‌های امیرالمؤمنین را رعایت کرده و استحقاق ایجاد کنید. تا موفق به تقوا و عمل به کلام نورانی باشید، تا حشرونشر شما با مولا باشد.\n ","بخش چهارم\nمتن:\nالتذكير بضُروب النعم:\nجَعَلَ لَكُمْ أَسْمَاعاً لِتَعِيَ مَا عَنَاهَا وَ أَبْصَاراً لِتَجْلُوَ عَنْ عَشَاهَا وَ أَشْلَاءً جَامِعَةً لِأَعْضَائِهَا مُلَائِمَةً لِأَحْنَائِهَا فِي تَرْكِيبِ صُوَرِهَا وَ مُدَدِ عُمُرِهَا بِأَبْدَانٍ قَائِمَةٍ بِأَرْفَاقِهَا وَ قُلُوبٍ رَائِدَةٍ لِأَرْزَاقِهَا فِي مُجَلِّلَاتِ نِعَمِهِ وَ مُوجِبَاتِ مِنَنِهِ وَ حَوَاجِزِ عَافِيَتِهِ، وَ قَدَّرَ لَكُمْ أَعْمَاراً سَتَرَهَا عَنْكُمْ وَ خَلَّفَ لَكُمْ عِبَراً مِنْ آثَارِ الْمَاضِينَ قَبْلَكُمْ مِنْ مُسْتَمْتَعِ خَلَاقِهِمْ وَ مُسْتَفْسَحِ خَنَاقِهِمْ أَرْهَقَتْهُمُ الْمَنَايَا دُونَ الْآمَالِ وَ شَذَّبَهُمْ عَنْهَا تَخَرُّمُ الْآجَالِ، لَمْ يَمْهَدُوا فِي سَلَامَةِ الْأَبْدَانِ وَ لَمْ يَعْتَبِرُوا فِي أُنُفِ الْأَوَانِ.\nفَهَلْ يَنْتَظِرُ أَهْلُ بَضَاضَةِ الشَّبَابِ إِلَّا حَوَانِيَ الْهَرَمِ وَ أَهْلُ غَضَارَةِ الصِّحَّةِ إِلَّا نَوَازِلَ السَّقَمِ وَ أَهْلُ مُدَّةِ الْبَقَاءِ إِلَّا آوِنَةَ الْفَنَاءِ مَعَ قُرْبِ الزِّيَالِ وَ أُزُوفِ الِانْتِقَالِ وَ عَلَزِ الْقَلَقِ وَ أَلَمِ الْمَضَضِ وَ غُصَصِ الْجَرَضِ وَ تَلَفُّتِ الِاسْتِغَاثَةِ بِنُصْرَةِ الْحَفَدَةِ وَ الْأَقْرِبَاءِ وَ الْأَعِزَّةِ وَ الْقُرَنَاءِ فَهَلْ دَفَعَتِ الْأَقَارِبُ أَوْ نَفَعَتِ النَّوَاحِبُ وَ قَدْ غُودِرَ فِي مَحَلَّةِ الْأَمْوَاتِ رَهِيناً وَ فِي ضِيقِ الْمَضْجَعِ وَحِيداً قَدْ هَتَكَتِ الْهَوَامُّ جِلْدَتَهُ وَ أَبْلَتِ النَّوَاهِكُ جِدَّتَهُ وَ عَفَتِ الْعَوَاصِفُ آثَارَهُ وَ مَحَا الْحَدَثَانُ مَعَالِمَهُ وَ صَارَتِ الْأَجْسَادُ شَحِبَةً بَعْدَ بَضَّتِهَا وَ الْعِظَامُ نَخِرَةً بَعْدَ قُوَّتِهَا وَ الْأَرْوَاحُ مُرْتَهَنَةً بِثِقَلِ أَعْبَائِهَا مُوقِنَةً بِغَيْبِ أَنْبَائِهَا لَا تُسْتَزَادُ مِنْ صَالِحِ عَمَلِهَا وَ لَا تُسْتَعْتَبُ مِنْ سَيِّئِ زَلَلِهَا أَوَ لَسْتُمْ أَبْنَاءَ الْقَوْمِ وَ الْآبَاءَ وَ إِخْوَانَهُمْ وَ الْأَقْرِبَاءَ تَحْتَذُونَ أَمْثِلَتَهُمْ وَ تَرْكَبُونَ قِدَّتَهُمْ وَ تَطَئُونَ جَادَّتَهُمْ فَالْقُلُوبُ قَاسِيَةٌ عَنْ حَظِّهَا لَاهِيَةٌ عَنْ رُشْدِهَا سَالِكَةٌ فِي غَيْرِ مِضْمَارِهَا كَأَنَّ الْمَعْنِيَّ سِوَاهَا وَ كَأَنَّ الرُّشْدَ فِي إِحْرَازِ دُنْيَاهَا. وَ اعْلَمُوا أَنَّ مَجَازَكُمْ عَلَى الصِّرَاطِ وَ مَزَالِقِ دَحْضِهِ وَ أَهَاوِيلِ زَلَلِـهِ وَ تَارَاتِ أَهْوَالِهِ.\nترجمه:\n(خداوند) براى شما گوش هايى قرار داد که آنچه را برايش اهميّت دارد، بشنود و حفظ کند، و چشمهايى که تاريکى ها را کنار زند و حقايق را (آن گونه که هست ببيند) و نيز بدنهايى قرار داد که اعضا را در بر گرفته است و در ترکيب بندى و تداوم عمر، هماهنگ با يکديگرند; با بدنهايى که تمام امکانات را در بردارد، و دلهايى که جوينده انواع روزى ها (و مواهب الهى) است و براى آن دقيقاً برنامه ريزى مى کند، تا نعمت هاى فراگير الهى و مواهب گوناگون او را به دست آورد، و از آنچه مانع عافيت و سلامت است بپرهيزد; و نيز عمرهايى براى شما مقدّر فرمود که مقدار دقيق آن از شما پنهان است.\nو از آثار گذشتگان درس هاى عبرت برايتان ذخيره کرده (که مايه بيدارى و هوشيارى شماست): از لذاتّى که از دنيا بردند و مواهبى که پيش از گلوگير شدن مرگ، از آن بهره مند شدند; ولى سرانجام پنجه مرگ، گريبان آنها را گرفت و ميان آنها و آرزوها جدايى افکند و با فرارسيدن اجل، دامنه آرزوها را برچيد، اين در حالى بود که به هنگام سلامت، چيزى براى خود نيندوختند و در آغاز زندگى (براى پايانش) عبرت نگرفتند.\nآيا جوانانِ شاداب، انتظارى جز خميدگى پيرى دارند; و آيا آنها که برخوردار از نعمت تندرستى کامل هستند، جز انواع بيمارى ها را چشم به راه مى باشند؟ و آيا کسانى که از بقا، برخوردارند جز لحظات فنا را منتظرند؟ اينها همه در حالى است که هنگام فراق و جدايى و لرزه و اضطراب، و ناراحتىِ مصيبت، و چشيدن طعم تلخ مصايب، و فروبردن جرعه هاى درد و رنج، و گردش چشم به اطراف، براى کمک خواهى و يارى جستن از فرزندان و نزديکان و عزيزان و هم قطاران، فرا رسيده است!\nآيا آنها (بستگان و نزديکان) مى توانند مرگى را از او دفع کنند و يا ناله و شيون هاى آنان براى او سودى دارد؟ در حالى که به محلّه مردگان سپرده شده، در تنگناى قبر تنها مانده است، حشرات موذى پوست تن او را از هم مى شکافند و سختى هاى گور بدن او را مى پوساند، تندبادها آثارش را نابود مى کند و گذشت شب و روز نشانه هاى او را از ميان بر مى دارد; بدنها، پس از طراوت، پژمرده و دگرگون مى شوند و استخوانها بعد از توانايى و قدرت، مى پوسند و متلاشى مى شوند. اين در حالى است که ارواح در گرو مسئوليّت سنگين اعمال خويش اند و در آنجا به اسرار نهانِ (قيامت که در اين جهان، باديده ترديد به آن نگاه مى کردند) يقين حاصل مى کنند; (از همه دردناکتر اينکه) نه بر اعمال صالحشان چيزى افزوده مى شود و نه از اعمال زشتشان مى توانند توبه کنند.\nآيا شما فرزندان و پدران و برادران همان مردم نيستيد؟ شما نيز همان برنامه ها را دنبال مى کنيد و برهمان طريقه سوار هستيد و در همان جادّه گام بر مى داريد (و سرانجام به همان سرنوشت گرفتار خواهيد شد!) ولى افسوس که دلها از گرفتن بهره خويش سخت و ناتوان شده و از رشد معنوى خود، غافل گشته و در غير طريق حقّ، گام بر مى دارد، گويى غير آنها مقصود هستند (و مرگ هرگز به سراغ آنها نمى آيد) و گويى نجات و رستگارى آنها، در به چنگ آوردن دنياست.\nبدانيد عبور شما از صراط و گذرگاهِ خطرناک مردافکن آن است! مَعبرى که قدمها در آن مى لغزد و خطرات هولناکى، پى درپى دامان انسان را مى گيرد.\nتفسیر:\n«خُطْبَةُ الْغَرَّاءِ»\nسیدرضی بخشی از خطبه را به دلیل طولانی‌بودن حذف کرده. حضرت می‌فرمایند؛\n«جَعَلَ لَکمْ أَسْمَاعًا لِتَعِی مَا عَنَاهَا»\nخدا برای شما گوش‌هایی قرار داده تا انسان آنچه را مهم و شایستهٔ توجه و عنایت است، بفهمد [لِتَعِی] و هر سخن بیهوده‌ای را نشنود؛ بلکه آنچه برای رشد انسان مهم است، بشنود.\n«وَأَبْصَارًا لِتَجْلُوَ عَنْ عَشَاهَا»\nو دو چشم به انسان داده تا تاریکی‌ها [عَشَاهَا] را آشکار کند.\nدو معنا دارد:\nکاربرد دو چشم برای دیدن جلوی پای خود و اشتباه‌نکردن.\nپشت سر گذاشتن تاریکی‌های دنیا با عبرت‌گرفتن.\nدلیل چشم‌داشتن صرفاً دیدنِ زیور و زینت دنیا نیست؛ خدا چشم را برای دیدن باطن به انسان داده است.\n«أَشْلَاءً جَامِعَةً لِأَعْضَائِهَا»\nای انسان، خدا به تو بدنی [أَشْلَاءً] داده که اعضای کوچک را دربرگرفته است. کل بدن از جزءهای کوچک تشکیل شده است.\nدستی که از مویرگ‌ها، عصب‌های مختلف، ماهیچه، غضروف و استخوان ساخته شده، در همین عضو قرار دارد. فقط همین نیست؛ میلیون‌ها چیزِ پنهان دیگر هم دارد. عالم هم همین‌طور است؛ از اجزا و اعضای فراوانی تشکیل شده است.\n«مُلَائِمَةً لِأَحْنَائِهَا فِی تَرْکیبِ صُوَرِهَا وَمُدَدِ عُمُرِهَا»\nتمام انحنای بدن، کجی و معوجی آن، با هم هماهنگ [مُلَائِمَةً] هستند.\nاین اعضای کوچک با هم هماهنگی دارند. استخوان صافِ دست و استخوان نیم‌دایرهٔ قفسهٔ سینه، هرکدام زاویه و قوس خاص خود را دارند؛ اما با هم هماهنگ‌اند تا مردم راحت باشند و به عبودیت بپردازند.\nدو ویژگی دارد:\nصورت‌هایی هستند که ترکیب شده‌اند [تَرْکیبِ صُورِهَا]؛ مثلاً چشم انسان در کاسهٔ سر قرار گرفته است. افزون بر زیبایی، کارایی هم دارد؛ یعنی ترکیب و صورتی دارد که کارکردی دقیق دارد و ظاهری قابل‌پذیرش.\nعمرشان بادوام است [مُدَدِ عُمُرِهَا].\nآنچه خدا خلق کرده، عمرِ همهٔ اعضا متناسب با هم است. برای سن نود سال، عمر، زندگی، دندان و چشمِ متناسب با آن را داده است تا مطابق سن او پیش برود و ببیند. امروزه به‌واسطهٔ تغذیهٔ غلط، خواب ناصحیح و آلودگی هوا، اعضا در جوانی معیوب می‌شوند.\n🔺 یکی از ادلهٔ طول عمر حضرت صاحب‌الزمان (عج) همین جملات بالاست که یکی از وجوه این ویژگی حضرت که معجزه است، به شمار می‌رود؛ جدای از آن، انسان با تغذیهٔ درست و سالم می‌تواند عمر طولانی داشته باشد.\n«قَائِمَةً بِأَرْفَاقِهَا»\nخداوند بدن‌هایی داده که استوار و قائم هستند و هرکدام می‌توانند منافع [أَرْفَاقِهَا] خود را کسب کنند. در آفتاب، پوست بدن به طور خودکار در حال ذخیرهٔ انرژی و جذب اکسیژن به داخل بدن است. هنگام خطر، چشم بی‌اختیار بسته می‌شود. بدن‌ها به دنبال کسب منافع خود هستند.\n«وَقُلُوبٍ رَائِدَةً لِأَرْزَاقِهَا»\nو قلوبی به شما داده که طالب و جست‌وجوگر [رَائِدَةً] رزق خود هستند.\nسه معنا برای این طالبِ رزق بودنِ قلب ذکر کرده‌اند:\nقلب خون‌رسانی می‌کند و خون را به تک‌تک سلول‌های بدن می‌رساند.\nقلب می‌تواند به معنای عقل باشد که تدبیر می‌کند و انسان معاش خود را تأمین می‌کند.\nقلب به معنای باطنی؛ خدا قلب و فطرتی به انسان داده که رزق آن معارف و محبتِ علی علیه‌السلام است.\n«فِی مُجَلِّلَاتِ نِعَمِهِ وَمُوجِبَاتِ مِنَنِهِ وَحَوَاجِزِ عَافِیتِهِ»\nقلب در این نعمت‌های گسترده [مُجَلِّلَاتِ]، مادی و معنوی که خدا قرار داده و آن‌قدر نعمت داده که موجب منت‌گذاشتن خدا می‌شود، رزقِ مادی و معنویِ خود را طلب می‌کند.\nقلب رزق خود را در سلامتی و کنارزدن موانع [حَوَاجِزِ] می‌تواند به دست آورد.\nانسان اگر آداب را رعایت کند، بیمار نمی‌شود؛ پس رزق او بیشتر می‌شود و امکان استفاده هم دارد.\nمثال: در ایام بیماری، کار تعطیل می‌شود؛ پول و رزق مادی هم در روزهای بیماری تعطیل می‌شود.\n«وَقَدَّرَ لَکمْ أَعْمَارًا سَتَرَهَا عَنْکمْ وَخَلَّفَ لَکمْ عِبَرًا مِنْ آثَارِ الْمَاضِینَ قَبْلَکمْ»\nدر کنار جسم و بدنی که خدا به شما داده، نعمتِ عمر است که مدت و مرگِ آن بر شما پوشیده است و خدا عبرت‌هایی از گذشتگان [آثَارِ الْمَاضِینَ] برای شما به‌جای گذاشته است. مؤمن به این آثارِ برجامانده نگاهِ عبرت‌بین دارد و غیر مؤمن فقط شکوه و عظمتِ بنا را می‌بیند.\n🔺 تفاوت در آثارِ عبرت‌آموز و فرهنگی است. تخت‌جمشید یکی از آثار عبرت‌آموز است. راین یک اثر فرهنگی است. این آثار باید در دست مؤمنان باشد؛ چون آن‌ها عبرت می‌گیرند، ولی کسی که اعتقاد ندارد اصلاً عبرتی نمی‌گیرد.\n🔅 ویژگیِ این گذشتگانی که عبرت‌آموز هستند:\n«مِنْ مُسْتَمْتَعِ خَلَاقِهِمْ وَمُسْتَفْسَحِ خِنَاقِهِمْ وَلَمْ یعْتَبِرُوا فِی أُنُفِ الْأَوَانِ»\nهمان گذشتگانی که بهره و لذت‌هایی [مُسْتَمْتَعِ] از این زندگی بردند.\nهمان‌هایی که طناب مرگ [خِنَاقِهِمْ] دور گردن آنان شل [مُسْتَفْسَحِ] بود. انسان از بدو تولد، طنابی دور گردنش انداخته شده و چند سال حیات، این طناب شل است؛ اما هنگام مرگ، این طنابِ دور گردن محکم کشیده می‌شود و کار تمام می‌شود.\n«أَرْهَقَتْهُمُ الْمَنَایا دُونَ الْآمَالِ وَشَذَّبَهُمْ عَنْهَا تَخَرُّمُ الْآجَالِ»\nبا فرارسیدن زمان مرگ، آن‌ها را شتابان فراگرفت [أَرْهَقَتْهُمْ] و از آرزوها دور کرد؛ همان مرگی که بین آن‌ها و آرزوهایشان جدایی انداخت. ازدواج ناکام، ساختمان ناتمام، آمالِ ناتمام؛ همه تمام می‌شود. فرصت، قدرت، تاج‌وتخت داشتند، اما با تمام‌شدن وقت، فرصت آن‌ها هم تمام شد.\nمرگِ ناگهانی [شَذَّبَهُمْ] آن‌ها را از آرزوهایشان جدا کرد. در قبر جایی برای آرزو نیست؛ آنجا جای دیدنِ حقایق است.\n«لَمْ یمْهَدُوا فِی سَلَامَةِ الْأَبْدَانِ»\nگذشتگانی که در حالت سلامتِ جسم هیچ توشه‌ای برای آخرت مهیا نکردند [لَمْ یمْهَدُوا].\nاوایلِ جوانی [أُنُفِ] سلامتِ بدن بود؛ اما هیچ عبرتی نبود. آمادگی و توشه‌ای برای سفر وجود نداشت.\n«فَهَلْ ینْتَظِرُ أَهْلُ بَضَاضَةِ الشَّبَابِ إِلَّا حَوَانِی الْهَرَمِ وَأَهْلُ غَضَارَةِ الصِّحَّةِ إِلَّا نَوَازِلَ السَّقَمِ»\nآیا جوان‌های امروز در اوج جوانی چیزی جز پیری را انتظار می‌کشند؟ آیا کسانی که امروز در اوج سلامتی هستند، چیزی جز مصیبت، گرفتاری و بیماری را انتظار می‌کشند؟\nکسانی که امروز در دوران بقا هستند، چیزی جز مرگ و نابودی را انتظار نمی‌کشند؟\n«مَعَ قُرْبِ الزِّیالِ وَأُزُوفِ الِانْتِقَالِ وَعَلَزِ الْقَلَقِ وَأَلَمِ الْمَضَضِ وَغُصَصِ الْجَرَضِ»\nروزی شما می‌میرید درحالی‌که:\nاین مرگ، انتقال از این دنیا، بسیار نزدیک [أُزُوفِ] است.\nاضطراب و ناراحتیِ لحظهٔ احتضار [عَلَزِ الْقَلَقِ] بسیار سخت است.\nدردهای جانکاه و جان‌سوز به شما نزدیک است [أَلَمِ الْمَضَضِ].\nآن لحظه که آب دهان در گلو افتاده و نمی‌توانید آن را بیرون بریزید، خفگی نزدیک است [غُصَصِ الْجَرَضِ].\nانتظارِ مرگ را هرگز دور مپندارید.\n«وَتَلَفُّتِ الِاسْتِغَاثَةِ بِنُصْرَةِ الْحَفَدَةِ وَالْأَقْرِبَاءِ وَالْأَعِزَّةِ وَالْقُرَنَاءِ»\nلحظه‌ای که حالت احتضار فرامی‌رسد و ملک‌الموت بالای سر است، فقط توجه، گردشِ چشم [تَلَفُّتِ] و التماس و استغاثه می‌کنید که کسی شما را یاری کند.\nزبان ازکارافتاده است؛ فقط چرخشِ نگاهِ چشم به بچه‌ها [حَفَدَةِ]، نزدیکان، عزیزان و هم‌نشینان است، اما کاری از دست کسی برنمی‌آید.\n«فَهَلْ دَفَعَتِ الْأَقَارِبُ أَوْ نَفَعَتِ النَّوَاحِبُ»\nآیا نزدیکان و دوستان می‌توانند ملک‌الموت و مرگ را دفع کنند؟!\nآیا اشک ریختن و نوحه‌سرایی [النَّوَاحِبُ] سودی به حال محتضر دارد؟!\n«وَقَدْ غُودِرَ فِی مَحَلِّهِ الْأَمْوَاتِ رَهِینًا وَفِی ضِیقِ الْمَضْجَعِ وَحِیدًا»\nمیت را در محلهٔ اموات می‌گذارند و به اموات می‌سپارند و بعد او را رها می‌کنند [غُودِرَ]، درحالی‌که تک‌وتنها در تنگنای قبر باقی می‌ماند.\n«قَدْ هَتَکتِ الْهَوَامُّ جِلْدَتَهُ وَأَبْلَتِ النَّوَاهِک جِدَّتَهُ»\nحشرات و موریانه‌ها در قبر به‌سوی شما آمده و پوست [جِلْدَتَهُ] شما را، به سبب این حشرات، از هم جدا و شکافته می‌کنند [هَتَکتْ].\nسختی و تنگی، فشارِ قبر، گرما، تاریکی، رطوبت و خون در رگِ خشکیدهٔ بدن، او را آمادهٔ پوسیدگی می‌کند.\n«وَعَفَتِ الْعَوَاصِفُ آثَارَهُ وَمَحَا الْحَدَثَانُ مَعَالِمَهُ»\nبیرون از قبر هم تندباد [عَوَاصِفُ] حوادث می‌وزد و تمام آثار مرده را پاک می‌کند [عَفَتْ].\nشب‌وروز [الْحَدَثَانُ] می‌آیند و تمام نشانه‌های او را محو می‌کنند. فقط یک سنگِ قبری از او باقی می‌ماند، مگر اینکه آثار نیک و علم از او باقی‌مانده باشد. برای مردم عادی، تمام آثار محو می‌گردد.\n«صَارَتِ الْأَجْسَادُ شَحِبَةً بَعْدَ بَضَّتِهَا وَالْعِظَامُ نَخِرَةً بَعْدَ قُوَّتِهَا»\nجسدها بعد از طراوت و تازگی [بَضَّتِهَا] پژمرده می‌شوند [شَحِبَةً] و استخوان‌ها بعد از قوتی که داشتند، پوسیده می‌شوند.\n«وَالْأَرْوَاحُ مُرْتَهَنَةً بِثِقَلِ أَعْبَائِهَا مُوقِنَةً بِغَیبِ أَنْبَائِهَا»\nمیت می‌ماند و روح او.\nروح انسان در رهن و گروِ سنگینیِ اعمالِ خود است؛ اعمال یا از جهت معنوی سنگین‌اند یا از جهت گناه.\nانسان وقتی چشم از دنیا بست و به سرای دیگر چشم‌باز کرد، به خبرهای غیبی که به او می‌دادند یقین می‌یابد [مُوقِنَةً]. او پیش‌تر به خبر غیبی‌ای که به او می‌رسید، پوزخند می‌زد که فرصت بسیار است.\n✅ یقین قبل از مرگ خوب و سودبخش است؛ بعد از مرگ سودی ندارد. بعد از مرگ، بالاجبار اعتقاد پیدا می‌کند و یقین حاصل می‌شود؛ درحالی‌که امروز در دنیا باید یقین را به دست آورد.\n«لَا تُسْتَزَادُ مِنْ صَالِحِ عَمَلِهَا وَلَا تُسْتَعْتَبُ مِنْ سَی»\nمرگ که عارض شد، انجام اعمال صالح در کار نیست، مگر با خیرات دیگران؛ از طرف خودِ او همه‌چیزتمام و پرونده بسته شد.\nو طلبِ رضایت [تُسْتَعْتَبُ] از خلق و خدا دیگر ممکن نیست.\n«أَوَلَسْتُمْ أَبْنَاءَ الْقَوْمِ وَالْآبَاءَ وَإِخْوَانَهُمْ وَالْأَقْرِبَاءَ»\nآیا شما فرزندان همین قوم نیستید؟\nشما برادران و نزدیکانِ آن‌ها نیستید؟\n«تَحْتَذُونَ أَمْثِلَتَهُمْ وَتَرْکبُونَ قِدَّتَهُمْ»\nچرا مثل آن‌ها قدم برمی‌دارید [تَحْتَذُونَ] و سوار مرکبی می‌شوید که آن‌ها سوار شدند و در مسیرشان حرکت می‌کنید؟\n✅ هیچ ممکن نیست کسی مسیر اشتباه را طی کند و انسان خوبی بشود.\n«فَالْقُلُوبُ قَاسِیةٌ عَنْ حَظِّهَا لَاهِیةٌ عَنْ رُشْدِهَا سَالِکةٌ فِی غَیرِ مِضْمَارِهَا»\nبرای اینکه بهره و حظِّ خود را ببرید، قلبتان سخت شده است. لب شما از رشدکردن غافل [لَاهِیةٌ] مانده است.\nچرا قلب را در مسیری غیر از مسابقه [مِضْمَارِهَا] راه می‌برید؟\nمسیر مسابقه، مسیر تقواست نه مسیر دنیاطلبی.\n«کأَنَّ الْمَعْنِی سِوَاهَا وَکأَنَّ الرُّشْدَ فِی إِحْرَازِ دُنْیاهَا»\nمشکل شما این است که فکر می‌کنید مرگ [الْمَعْنِی] سراغ دیگران می‌رود و شما را نشانه نمی‌گیرد.\nشما گمان می‌کردید رشد در کسب دنیا است؛ حال‌آنکه رشد در دوری از دنیا و کسب آخرت است.\n«وَاعْلَمُوا أَنَّ مَجَازَکمْ عَلَی الصِّرَاطِ وَمَزَالِقِ دَحْضِهِ وَأَهَاوِیلِ زَلَلِهِ وَتَارَاتِ أَهْوَالِهِ»\nای مردم، بدانید که شما روزی از پل‌صراط عبور می‌کنید؛ روزی به لغزشگاه‌هایی که پاها در آن لرزان‌اند، معبرهای لغزش [أَهَاوِیلِ زَلَلِهِ] و هول و اضطرابِ پی‌درپی، گذر شما می‌افتد.\nغفر الله لی و لکم و الحمدلله رب‌العالمین","بخش پنجم\nمتن:\nفَاتَّقُوا اللَّهَ عِبَادَ اللَّهِ تَقِيَّةَ ذِي لُبٍّ شَغَلَ التَّفَكُّرُ قَلْبَهُ وَ أَنْصَبَ الْخَوْفُ بَدَنَهُ وَ أَسْهَرَ التَّهَجُّدُ غِرَارَ نَوْمِهِ وَ أَظْمَأَ الرَّجَاءُ هَوَاجِرَ يَوْمِهِ وَ ظَلَفَ الزُّهْدُ شَهَوَاتِهِ وَ أَوْجَفَ الذِّكْرُ بِلِسَانِهِ وَ قَدَّمَ الْخَوْفَ لِأَمَانِهِ وَ تَنَكَّبَ الْمَخَالِجَ عَنْ وَضَحِ السَّبِيلِ وَ سَلَكَ أَقْصَدَ الْمَسَالِكِ إِلَى النَّهْجِ الْمَطْلُوبِ وَ لَمْ تَفْتِلْهُ فَاتِلَاتُ الْغُرُورِ وَ لَمْ تَعْمَ عَلَيْهِ مُشْتَبِهَاتُ الْأُمُورِ ظَافِراً بِفَرْحَةِ الْبُشْرَى وَ رَاحَةِ النُّعْمَى فِي أَنْعَمِ نَوْمِهِ وَ آمَنِ يَوْمِهِ، وَ قَدْ عَبَرَ مَعْبَرَ الْعَاجِلَةِ حَمِيداً وَ قَدَّمَ زَادَ الْآجِلَةِ سَعِيداً وَ بَادَرَ مِنْ وَجَلٍ وَ أَكْمَشَ فِي مَهَلٍ وَ رَغِبَ فِي طَلَبٍ وَ ذَهَبَ عَنْ هَرَبٍ وَ رَاقَبَ فِي يَوْمِهِ غَدَهُ وَ نَظَرَ قُدُماً أَمَامَهُ، فَكَفَى بِالْجَنَّةِ ثَوَاباً وَ نَوَالًا وَ كَفَى بِالنَّارِ عِقَاباً وَ وَبَالًا وَ كَفَى بِاللَّهِ مُنْتَقِماً وَ نَصِيراً وَ كَفَى بِالْكِتَابِ حَجِيجاً وَ خَصِيماً. أُوصِيكُمْ بِتَقْوَى اللَّهِ الَّذِي أَعْذَرَ بِمَا أَنْذَرَ وَ احْتَجَّ بِمَا نَهَجَ وَ حَذَّرَكُمْ عَدُوّاً نَفَذَ فِي الصُّدُورِ خَفِيّاً وَ نَفَثَ فِي الْآذَانِ نَجِيّاً، فَأَضَلَّ وَ أَرْدَى وَ وَعَدَ فَمَنَّى وَ زَيَّنَ سَيِّئَاتِ الْجَرَائِمِ وَ هَوَّنَ مُوبِقَاتِ الْعَظَائِمِ حَتَّى إِذَا اسْتَدْرَجَ قَرِينَتَهُ وَ اسْتَغْلَقَ رَهِينَتَهُ أَنْكَرَ مَا زَيَّنَ وَ اسْتَعْظَمَ مَا هَوَّنَ وَ حَذَّرَ مَا أَمَّنَ.\nترجمه:\nاى بندگان خدا تقواى الهى پيشه کنيد! همچون تقواى خردمندى که تفکّر، قلب او را به خود مشغول ساخته و خوف الهى جسمش را خسته کرده، شب زنده دارى، خواب را از چشمش ربوده، اميد به رحمت پروردگار، او را به تشنگى روزه ايّام گرم (تابستان) واداشته، و زهد در دنيا خواهش هاى نفسانى را از او گرفته است;\nهمان پرهيزگارى که ذکر خدا به سرعت بر زبانش جارى شده و ترس (از خدا) را براى ايمنى رستاخيز از پيش فرستاده است; جاذبه هاى(انحرافى و شيطانى) را از جاده خويش کنار زده و در بهترين و مستقيم ترين راههايى که او را به روش مطلوب (جهت رسيدن به رضاى خدا) مى رساند، گام برداشته، و وسوسه ها و فريب ها هرگز او را نفريفته، و امور مشکوک بر او پنهان نمانده است (و به کمک نور تقوا، حق را از باطل تشخيص داده است) با مژده (بهشت) و زندگى آسوده، در ميان نعمتها، در بهترين جايگاه وايمن ترين روزها، شاد و مسرور است; اين در حالى است که از گذرگاه دنياى زودگذر، با روشى پسنديده عبور کرده و توشه آخرت را توأم با سعادت از پيش فرستاده است;\nهمان پرهيزگارى که از ترس (آن روز، به عمل صالح) مبادرت ورزيده و در مهلت (زندگى) با سرعت مشغول (بندگى) بوده و نسبت به آنچه مطلوب (پروردگار) است، رغبت کامل داشته و از آنچه بايد بگريزد دورى کرده است; امروز مراقب فرداى خويش است و براى آينده خود پيش بينى لازم را نموده است. همان بس که بهشت، پاداش و عطيه (پرهيزگاران) باشد! و همان بس که آتش دوزخ، کيفر (بدکاران و بى تقوايان) باشد و کافى است که خداوند انتقام گيرنده (از اينها) و يارى کننده (آنها) و قرآن مدافع (نيکوکاران) و دشمن (بدکاران) باشد!\nشما را به تقواى الهى سفارش مى کنم! همان خداوندى که با انذار و هشدار خود، راه عذر را بسته و با دلايل روشن، طريق هدايت را نشان داده و حجّت را تمام کرده است و شما را از دشمنى بر حذر داشته است که، مخفيانه در درون سينه هاى شما نفوذ مى کند و آهسته در گوش هاى شما مى دمد و (به اين طريق شما را) گمراه مى سازد و به هلاکت مى کشاند; او نويد مى دهد و انسان را به آرزوها(ى باطل و دور و دراز) سرگرم مى کند و گناهان و جرايم را در نظرها زيبا جلوه مى دهد و معاصى بزرگ را کم اهميّت مى شمرد (اين وضع همچنان ادامه مى يابد) تا به تدريج پيروان خود را فريب داده، درهاى سعادت را به روى گروگانِ خود ببندد (ولى در سراى آخرت که همگى در محضر عدل الهى حاضر مى شوند) شيطان آنچه را آراسته بود، انکار مى کند و آنچه را سبک جلوه داده بود، بزرگ مى شمرد و از آنچه فريب خوردگان را ايمن ساخته بود، بر حذر مى دارد (ولى افسوس که زمان جبران سپرى شده است!).\nتفسیر:\nخطبه‌الغرّاء\nامیرالمؤمنین صَلَوَاتُ اللهِ عَلَیهِ در بخش‌های گذشته، مرحله‌ای از خلقت انسان تا مرگ، و اصل مهمِ عبرت‌گرفتن از گذشتگان و تقوا را بیان فرمودند.\nفضای خطبه در حالتی است که مردم برای عزاداریِ عزیزان خود جمع شده‌اند، و حضرت توصیه‌های اخلاقی و مکرّرِ تقوا را یادآور می‌شود.\n♦️فَاتَّقُوا اللّهَ عِبَادَ اللّهِ تَقِیةَ ذِی لُبٍّ شَغَلَ التَّفَکرَ قَلْبَهُ\nبندگان خدا، پروای خدا را داشته باشید.\nتقوا یک حداقلی دارد و یک حداکثری.\nحضرت می‌خواهند مردم از حداقل تقوا رشد کنند و در همان حالت نمانند؛ بلکه از اخلاق به عرفان، خود را بالا بکشند.\nنهایتِ اخلاق این است که کارِ مردم به جایی برسد که غیر از مطالب ظاهر، باطن را هم ببینند و شنوای مطالبِ باطن هم باشند.\nتقواپیشه کنید؛ تقوای انسانِ عاقلِ [ذِی لُبٍّ] که تمام فکر و ذهن او به تقوا معطوف است؛ به‌گونه‌ای که تقوا تفکر را تحت‌تأثیر قرار بدهد، یعنی فکر به جایی برسد که از حالت روزمرگی خارج شود.\n♦️وَأَنْصَبَ الْخَوْفُ بَدَنَهُ وَأَسْهَرَ التَّهَجُّدُ غِرَارَ نَوْمِهِ\nتقوای انسانی که از خوفِ خدا، بدنِ خود را به رنج و سختی می‌اندازد.\nعبودیت در راحتی و آسایش نیست؛ برای رضای خدا باید زحمت را به جان خرید تا صاحب تقوا شد.\nبسانِ تقوای کسی که برای تهجّد و بیداریِ شبانه [أَسْهَرَ] خواب از چشمان او ربوده می‌شود.\nصاحب تقوا، نه‌فقط برای نماز صبح، بلکه برای نماز و بیداریِ شب، خواب ندارد. به حداقل اکتفا نمی‌کند.\n♦️وَأَظْمَأَ الرَّجَاءُ هَوَاجِرَ یوْمِهِ وَظَلَفَ الزَّهْدُ شَهَوَاتِهِ\nتقواپیشه کنید؛ مانند تقوای انسانی که امید به پاداشِ خدا، امید به جلبِ رضایتِ خدا، او را در گرمای روز [هَوَاجِرَ] تابستان تشنه کرده [أَظْمَأَ].\nآن‌چنان تقوایی که زهد، شهواتِ او را پایمال کرده [ظَلَفَ].\nزهد، تمام خواسته‌های معقولِ او را پایمال کرده است.\n♦️وَأَوْجَفَ الذِّکرُ بِلِسَانِهِ وَقَدَّمَ الْخَوْفُ لِأَمَانِهِ\nتقوایی که ذکرِ الهی را بر زبانِ او تیز و سریع کرده است. دو معنا دارد:\n۱- در هر اتفاقِ خوش یا ناخوش، ذکرِ خدا بر زبان جاری است و نامِ خدا بر هر چیز مقدم است.\n۲- اهل تقوا به‌خاطر انسِ فراوان با ذکر، طیّ اللسان دارند. در چند لحظه، زبان بیش از حالت عادی می‌چرخد؛ با سرعت، درست و با توجه، ذکر سرعت می‌گیرد.\nبسانِ تقوای کسی باشد که ترس از خدا را پیش فرستاده برای روزی که امنیت نیاز دارد. [لِأَمَانِهِ]\nکسی که در دنیا خوف داشته باشد، معکوسِ آن در قیامت از امنیت برخوردار است؛ اما کسی که در دنیا خود را در امنیت بداند، فردای قیامت در خوف به سر می‌برد.\n♦️وَتَتَکبَ الْمَخَالِجَ عَنْ وَضَحِ السَّبِیلِ\nتقوای انسانی که مشغله‌ها و مخارج او را از راهِ مستقیم به کناری نکشید [تَنْکبَ] تا منحرف شود.\nهیچ شخصی در عالم نیست که گرفتار نباشد؛ آیا گرفتاری و مشغله باید او را غافل کند؟!\nگرفتاری هرگز اهل تقوا را از نهجِ سبیل و از خدا جدا نمی‌کند.\n♦️وَسَلَک أَقْصَدَ الْمَسَالِک إِلَی النَّهْجِ الْمَطْلُوبِ\nتقوای کسب‌شدهٔ شما، مانند تقوای شخصی باشد که بهترین مقصد را انتخاب می‌کند و صحیح‌ترین راهِ رسیدن به مقصد را می‌پیماید.\n✅ برای عده‌ای ممکن است هدف درست باشد، اما برای رسیدن به آن از جاده‌های خاکی و کم‌ارزش عبور می‌کنند.\nمثال: برای کسب رضایتِ دلِ پدر و مادر نباید از مسیری باشد که زن و فرزند برنجد.\nهم بهترین مقصد و هم بهترین راه، می‌شود تقوای الهی.\n♦️وَلَمْ تَفْتِلْهُ فَاتِلَاتُ الْغُرُورِ\nتقواپیشه کنید؛ مانند تقوای کسی که تردیدهای غرورانگیز او را مردد نکرده [لَمْ تَفْتِلْهُ].\nهیچ‌چیز، نه شیطان، نه وهم، او را مردد نمی‌کند. محکم و استوار جلو می‌رود و در میانهٔ راه، دست‌ودل او نمی‌لرزد.\n✅ اگر استواری در کار نباشد، پیوسته از یک کار خوب به شاخه‌ای و به کار خوبِ دیگر می‌پرد. برای شیطان همین بس که تو را این‌گونه مشغول کند.\n♦️وَلَمْ تَعْمَ عَلَیهِ مُشْتَبِهَاتُ الأُمُورِ\nامورِ مشتبه و مشکوک برای او بسته نیست؛ [لَا تَعْمَ] دستِ او از رسیدن به حقیقت کوتاه نیست. تقوا سببِ بصیرتِ او شده است؛ به هر چیزی بنگرد، درست یا نادرست بودنِ آن را تشخیص می‌دهد. ظاهرِ خوب، ولی باطنِ فتنه و آتش را تشخیص می‌دهد.\n♦️ظَافِرًا بِفَرْحَةِ الْبُشْرَی وَرَاحَةِ النُّعْمَی\nشخصی که به چنین تقوایی برسد، پیروز شده [ظَافِرًا]، به بشارت و شادمانی دست‌یافته و در قیامت به زندگیِ سرتاسر آرامش و نعمت می‌رسد.\n♦️فِی أَنْعَمِ نَوْمِهِ وَآمَنِ یوْمِهِ\nدر بهترین جایگاه و بهترین روز، در امنیت و آرامش به سر می‌برد.\n♦️قَدْ عَبَرَ مَعْبَرَ الْعَاجِلَةِ حَمِیدًا وَقَدَّمَ زَادَ الْآجِلَةِ سَعِیدًا\nکسی که از معبرِ دنیا [الْعَاجِلَةِ] با روش و منشِ پسندیده عبور کند و آن را پیش بفرستد تا در آخرت [الْآجِلَةِ] سعادتمند باشد.\nکسانی می‌توانند صراطِ قیامت را با آرامش طی کنند که صراطِ دنیا را با آرامش طی کرده باشند. صراطِ آخرت، نمودِ صراطِ دنیاست.\n♦️وَبَادَرَ مِنْ وَجَلٍ وَأَکمَشَ فِی مَهَلٍ\nکسی که خوفِ الهی دارد، به عمل مبادرت می‌ورزد. [بَادَرَ]\nترس باید انسان را به عمل وارد کند؛ مبادرت‌ورزیدن و سرعت‌بخشیدن به عملِ خیر، نشانِ تقواست.\nمانند تقوای کسی که در طول عمرِ خود شتاب کرد [أَکمَشَ].\nهر جا عملِ خیر دید، به کار خیر سرعت بخشید.\n♦️وَرَغِبَ فِی طَلَبٍ وَذَهَبَ عَنْ هَرَبٍ\nبه رضایتِ الهی رغبتِ کامل دارد.\nرغبتِ کامل برای هر امری که رضایتِ خدا باشد؛ رغبتِ او نصفه‌ونیمه نیست.\nدر امور مالی راغب باشد، در امور جهادی نه!\nدر امرِ جهاد راغب باشد، در امرِ انفاق دست‌ودل بلرزد!\nبه طور کامل در هر امری راغب است.\nتقوایی که او را از آنچه خدا نهی کرده دور می‌کند [ذَهَبَ عَنْ هَرَبٍ]، از منطقهٔ ممنوعه فرار می‌کند.\n♦️وَرَاقَبَ فِی یوْمِهِ غَدَهُ\nتقواپیشه کنید؛ مانند تقوای انسانی که دنیا را با مراقبت [رَاقَبَ] سپری می‌کند برای بعد از مرگ و قیامت [غَدَهُ].\n♦️وَنَظَرَ قُدُماً أَمَامَهُ\nبرای آینده و قیامتِ پیشرو، تفکر و تأمل دارد.\nبه هر مجلسی، به هر سفری وارد نمی‌شود.\nپیش‌بینی و آینده‌نگری می‌کند، بی‌گدار به آب نمی‌زند.\n♦️فَکفَیٰ بِالْجَنَّةِ ثَوَابًا وَنَوَالًا وَکفَیٰ بِاللَّهِ عِقَابًا وَوَبَالًا وَکفَیٰ بِاللَّهِ مُنْتَقِمًا وَنَصِیرًا\nبرای اهل تقوا، بهترین ثواب و پاداش [نَوَالًا] بهشت است و خدا آنان را کفایت می‌کند.\nخدای متعال برای منتقم بودن و هم برای یاری‌کردن، کفایت می‌کند.\nو برای متقی همین بس که در هول و اضطرابِ قیامت، یاورِ او خدا باشد.\n♦️وَکفَیٰ بِالْکتَابِ حَجِیجًا وَخَصِیمًا\nکتابِ قرآن کفایت می‌کند برای متقی که حجت باشد. قرآن شفیع و دستگیرِ او باشد، و حجتِ او باشد که به قرآن عمل می‌کرد.\nقرآن زنده است؛ حیات و نور دارد و به نفع و ضررِ کسی می‌تواند شهادت بدهد.\n♦️أُوصِیکمْ بِتَقْوَی اللَّهِ الَّذِی أَعْذَرَ بِمَا أَنْذَرَ وَاحْتَجَّ بِمَا نَهَجَ\nبندگان خدا، شما را به تقوای خدا توصیه می‌کنم؛ خدایی که به‌واسطهٔ انذار، راهِ عذرآوردن را بست. خدا راهِ روشن و حجت‌ها را نشان داد؛ بعد از حجت‌ها اگر تقوا نباشد، هیچ بهانه و عذری پذیرفته نیست.\n♦️وَحَذَّرَکمْ عَدُوًّا نَفَذَ فِی الصُّدُورِ خَفِیا\nحضرت به دشمنِ تقوا اشاره می‌فرماید:\nخدا شما را برحذر داشت و آژیرِ خطر را برای شما کشید؛ بدانید دشمنِ شما شیطان است و پنهانی در شما نفوذ می‌کند [نَفَذَ خَفِیا].\n✅ خطرِ نفوذِ او در لباسِ خودی آن‌چنان ریز و دقیق است که عالِم را با روایات از پا درمی‌آورد و فهمِ او را از درک متوقف می‌کند.\n♦️وَنَفَثَ فِی الْآذَانِ نَجِیا\nدر گوش به‌آهستگی نجوا می‌کند.\nشیطان می‌دمد [نَفَثَ]، تعصب را برمی‌انگیزد تا مقابله‌به‌مثل صورت بگیرد و سرانجام، کسی که اختیارِ خود را به شیطان واگذارد.\n♦️فَأَضَلَّ وَأَرْدَیٰ وَوَعَدَ فَمَنَّیٰ\nگمراهی، و وعده، تمنّا می‌دهد.\nشیطان تمام وعده را به آرزوهای پوچ تبدیل می‌کند. وعده‌های او خیالی است و آن‌ها را کتمان می‌کند. اما وعدهٔ خدا صدق است.\n«وَقَالَ الشَّیطَانُ لَمَّا قُضِی الْأَمْرُ إِنَّ اللَّهَ وَعَدَکمْ وَعْدَ الْحَقِّ وَوَعَدْتُکمْ فَأَخْلَفْتُکمْ …… أَلَا أَنْ دَعَوْتُکمْ فَاسْتَجَبْتُمْ لِی …. إِنِّی کفَرْتُ بِمَا أَشْرَکتُمُونِ مِنْ قَبْلِ إِبْرَاهِیمَ - ۲۲»\nشیطان در مواجههٔ آخرتی، به تابعینِ خود می‌گوید: خدا وعده‌های صادق داد؛ چرا دنبال آن نرفتید؟ من وعده دادم و تخلف کردم؛ اما شما دعوتِ مرا اجابت کردید. من از شما بیزارم به‌خاطر عمل‌هایی که در دنیا داشتید.\nمرا ملامت نکنید و خود را ملامت کنید.\n♦️وَزَینَ سَیئَاتِ الْجَرَائِمِ وَهَوَّنَ مُوبِقَاتِ الْعَظَائِمِ\nشیطان سیئه و جرائم را زینت می‌دهد و گناهانِ بزرگ را کوچک و حقیر [هَوَّنَ] نشان می‌دهد.\nبا وعدهٔ «این گناه که چیزی نیست، دیگران بدتر و بزرگ‌تر از این انجام می‌دهند» عملِ زشت را کوچک و کوچک می‌کند تا وسواسِ او…\n♦️حَتَّیٰ إِذَا اسْتَدْرَجَ قَرِینَتَهُ وَاسْتَغْلَقَ رَهِینَتَهُ\nبه‌تدریج او را فریب می‌دهد تا اینکه او را قرینِ خود کند.\nفردی که باخدا بود؛ اما چنان او را جدا کرد که دنباله‌روِ شیطان شد، بعد از پیروی از او قرین می‌شود.\nحضرت به شیطان زده‌ها، جفت و هم‌قرینِ شیطان خطاب می‌کند که بعد از مدتی نمی‌تواند از شیطان جدا شود.\nاو را اسیرِ خودکرده و در را بر روی اسیر قفل می‌کند [اسْتَغْلَقَ].\nمانند اعتیادی که شیطان‌صفتان ابتدا جنسِ خوب، رایگان، بعد باقیمت ارزان در اختیار قرار می‌دهند؛ گرفتار که شد، او دنباله‌رو شده، نمی‌تواند دست بردارد. به‌آرامی وارد می‌شود، تحت‌تأثیر قرار می‌دهد تا جایی که اسیر و گرفتار شد، سپس:\n♦️أَنْکرَ مَا زَینَ وَاسْتَعْظَمَ مَا هَوَّنَ وَحَذَّرَ مَا أَمِنَ\nآنچه را تزیین داده بود انکار می‌کند.\nو بزرگ می‌شمارد [اسْتَعْظَمَ] گناهی را که در دنیا سبک می‌شمرد.\nبرحذر می‌دارد از آنچه گفته بود، «در امنیت هستید، من با شما هستم»؛ وقتی پای او به قیامت باز شد و جهنم را به عینه دید، انکار و وعده‌ها را کتمان می‌کند، گویی اصلاً چیزی نبوده.\n«وَإِذْ زَینَ لَهُمُ الشَّیطَانُ أَعْمَالَهُمْ وَقَالَ لَا غَالِبَ لَکمُ الْیوْمَ وَإِنِّی جَارٌ لَکمْ فَلَمَّا تَرَاءَتْ …… وَقَالَ إِنِّی بَرِیءٌ مِنْکمْ أَنْفَالَ - ۴۸»\nوقتی شیطان اعمالِ زشت را زینت داد و گفت امروز کسی بر شما غالب نیست، در بحران من با شما هستم؛ اما زمانی که با حقیقت روبه‌رو شد، وعده‌ها را کتمان کرده و اعلامِ برائت می‌کند.\n✅ بندگان خدا، دشمنِ اصلی شیطان است؛ مبادا تحت‌تأثیر وسوسه و وعده‌های زیبای شیطان قرار بگیرید. تا خسرالدنیا و الآخرة نکند، دست‌بردار نیست.\n✅ حدیث قدسی: خطاب به موسی بن عمران: تا وقتی خبرِ مرگِ شیطان به تو نرسیده، از مکر و شیطنتِ او خود را در امان نبین.\nاللهم نَعُوذُ بِک أَنْ یحْضُرُونَ","بخش ششم\nمتن:\nو منها في صفة خلق الإنسان:\nأَمْ هَذَا الَّذِي أَنْشَأَهُ فِي ظُلُمَاتِ الْأَرْحَامِ وَ شُغُفِ الْأَسْتَارِ نُطْفَةً دِهَاقاً وَ عَلَقَةً مِحَاقاً وَ جَنِيناً وَ رَاضِعاً وَ وَلِيداً وَ يَافِعاً، ثُمَّ مَنَحَهُ قَلْباً حَافِظاً وَ لِسَاناً لَافِظاً وَ بَصَراً لَاحِظاً لِيَفْهَمَ مُعْتَبِراً وَ يُقَصِّرَ مُزْدَجِراً، حَتَّى إِذَا قَامَ اعْتِدَالُهُ وَ اسْتَوَى مِثَالُهُ نَفَرَ مُسْتَكْبِراً وَ خَبَطَ سَادِراً مَاتِحاً فِي غَرْبِ هَوَاهُ كَادِحاً سَعْياً لِدُنْيَاهُ فِي لَذَّاتِ طَرَبِهِ وَ بَدَوَاتِ أَرَبِهِ، ثُمَّ لَا يَحْتَسِبُ رَزِيَّةً وَ لَا يَخْشَعُ تَقِيَّةً، فَمَاتَ فِي فِتْنَتِهِ غَرِيراً وَ عَاشَ فِي هَفْوَتِهِ يَسِيراً لَمْ يُفِدْ عِوَضاً وَ لَمْ يَقْضِ مُفْتَرَضاً؛ دَهِمَتْهُ فَجَعَاتُ الْمَنِيَّةِ فِي غُبَّرِ جِمَاحِهِ وَ سَنَنِ مِرَاحِهِ فَظَلَّ سَادِراً وَ بَاتَ سَاهِراً فِي غَمَرَاتِ الْآلَامِ وَ طَوَارِقِ الْأَوْجَاعِ وَ الْأَسْقَامِ بَيْنَ أَخٍ شَقِيقٍ وَ وَالِدٍ شَفِيقٍ وَ دَاعِيَةٍ بِالْوَيْلِ جَزَعاً وَ لَادِمَةٍ لِلصَّدْرِ قَلَقاً وَ الْمَرْءُ فِي سَكْرَةٍ مُلْهِثَةٍ وَ غَمْرَةٍ كَارِثَةٍ وَ أَنَّةٍ مُوجِعَةٍ وَ جَذْبَةٍ مُكْرِبَةٍ وَ سَوْقَةٍ مُتْعِبَةٍ.\nثُمَّ أُدْرِجَ فِي أَكْفَانِهِ مُبْلِساً وَ جُذِبَ مُنْقَاداً سَلِساً، ثُمَّ أُلْقِيَ عَلَى الْأَعْوَادِ رَجِيعَ وَصَبٍ وَ نِضْوَ سَقَمٍ تَحْمِلُهُ حَفَدَةُ الْوِلْدَانِ وَ حَشَدَةُ الْإِخْوَانِ إِلَى دَارِ غُرْبَتِهِ وَ مُنْقَطَعِ زَوْرَتِهِ وَ مُفْرَدِ وَحْشَتِهِ، حَتَّى إِذَا انْصَرَفَ الْمُشَيِّعُ وَ رَجَعَ الْمُتَفَجِّعُ أُقْعِدَ فِي حُفْرَتِهِ نَجِيّاً لِبَهْتَةِ السُّؤَالِ وَ عَثْرَةِ الِامْتِحَانِ\nترجمه:\nهمين انسانى که خداوند او را در تاريکى هاى رحم و در پرده هاى متراکم، به صورت نطفه اى فرو ريخت; سپس او را به شکل خون بسته و نامشخّصى قرار داد و بعد از آن، به صورت جنين کامل، سپس نوزادى شيرخوار و بعد کودک، سپس نوجوانى درآورد و بعد از آن به او عقلى نگاهدارنده و زبانى گويا و چشمى بينا بخشيد، تا درک کند و عبرت گيرد و از بدى ها بپرهيزد و اين وضع ادامه مى يابد تا انسان به حدّ اعتدال و کمال برسد و بر پاى خود بايستد; در اين هنگام سرکشى کرده و مى گريزد و بى پروا در بى راهه گام مى نهد. اين در حالى است که سعى دارد به تمام هوس هاى خود جامه عمل بپوشاند و براى بدست آوردن دنيا، خود را به رنج و تعب بيفکند و براى لذّات آن پيوسته تلاش مى کند و هر چه از خواهش هاى نفسانى در فکرش خطور کند، به آن جامه عمل مى پوشاند;\nاو هرگز فکر نمى کند مصيبتى برايش پيش بيايد و هيچگاه از روى تقواى الهى در پيشگاهش خضوع نمى کند; از اين رو، سرانجام چشم از دنيا فرو مى بندد، در حالى که در گمراهى و غرور گرفتار است و در ميان اشتباهات و خطاهاى زندگى کوتاهِ خود، غوطه ور! اين در حالى است که در برابر آنچه از دست داده، عوضى بدست نياورده و هيچ يک از وظايف واجب خود را انجام نداده است.\n(هنوز تلاش و کوشش او در طريق اشباع هوسهايش پايان نگرفته که) ناراحتى هاى مرگ، در حالى که بقاياى سرکشى در او وجود دارد و در مسير لذّات خود گام برمى دارد، او را در خود فرو مى برد و ناگهان گرفتار حيرت و سرگردانى مى شود و از شدّت بيمارى و درد و رنج ها، شب تا به صبح بيدار مى ماند (و ناله سر مى دهد) اين در حالى است، که در ميان برادرى غمخوار، پدرى مهربان (وهمسرى دلسوز که) گريه و ناله سر داده اند (و مادرى دلسوخته که) از شدّت ناراحتى به سينه مى کوبد، قرار گرفته است و با سکراتِ بى تاب کننده مرگ و شدائد غم انگيز و ناله هاى دردناک و جان دادن پرمشقّت و مرگ رنج آور، دست به گريبان است.\nآن گاه پيكرش را در كفنها مى پيچند و او را، كه رام و تسليم است، از زمين بر مى گيرند و بر تخته پاره ها مى نهند و در حالى كه، از شدت تعب، چون اشتر از سفر بازگشته خسته است، از رنج بيمارى گداخته و لاغر شده است. فرزندان و برادرانش او را بردارند و به سراى غربتش برند، جايى كه كسى به ديدارش نرود. چون تشييع كنندگان و نوحه سرايان بازگردند، او را در قبرش بنشانند و او از بيم سؤال و لغزش در امتحان ياراى سخن گفتنش نباشد.\nتفسیر:\nشگفتی‌های آفرینش انسان\nأَمْ هَذَا الَّذِی أَنْشَأَهُ فِی ظُلُمَاتِ الْأَرْحَامِ وَشُغُفِ الْأَسْتَارِ نُطْفَةً دِهَاقًا وَعَلَقَةً مِحَاقًا\nمگر انسان همان نطفه و خون نیم‌بند نیست که خدا او را در تاریکی‌های رحم و غلاف‌های تودرتو پدید آورد؟\nهمین انسانی که امروز گردن‌کشی می‌کند، نطفه‌ای جهنده و تکه خونی بسته‌شده بود که قیافه و صورتی هم نداشت؟\nوَجَنِینًا وَرَاضِعًا\nتا به‌صورت جنین درآمد و سپس کودکی شیرخوار شد.\nبعد از مدتی، به جنینی درون شکم مادرش تبدیل شد. پس از آن نیز طفلی شیرخوار بود که نمی‌توانست پشه‌ای را از خود دفع کند یا نعمتی را برای خود جلب نماید.\nوَوَلِیدًا وَیافِعًا\nاین مراحل را یکی پس از دیگری سپری کرد.\nنوزادی بود که ابتدا خردسال و سپس جوان شد. آیا انسانی که این شش مرحله را طی کرده است، می‌خواهد بی‌تقوایی کند و در برابر خدا بایستد؟ او در آغاز هیچ نبود. ما او را آفریدیم؛ پس چرا خودبزرگ‌بینی می‌کند و خود را در برابر خدای متعال، صاحب جلال، می‌بیند؟\nثُمَّ مَنَحَهُ قَلْبًا حَافِظًا\nسپس خدا به او قلبی نگهدارنده و عقلی عطا کرد که بتواند بفهمد و حفظ کند. مدت‌ها باید می‌گذشت تا بتواند به درک و فهم برسد. ما به او عقل و فهم دادیم تا بیندیشد و بفهمد.\nوَلِسَانًا لَافِظًا\nو به انسان زبانی گویا دادیم تا سخنان درونی خود را به بیرون منتقل کند.\nوَبَصَرًا لَاحِظًا\nو چشمی بینا عطا فرمود؛ نه اینکه فقط به‌ظاهر اکتفا کند، بلکه بتواند عوالم را ملاحظه کند.\nلِیفْهَمَ مُعْتَبِرًا\nتا عبرت‌ها را درک کند.\nهمه‌ی این نعمت‌ها برای چیست؟ برای اینکه این انسان بفهمد و عبرت بگیرد.\nوَیقَصِّرَ مُزْدَجِرًا\nو از بدی‌ها بپرهیزد.\nاز اموری که او را از آن‌ها نهی کرده‌اند، دست بردارد. گوش و چشم و زبان و عقل و استعداد برای این نیستند که انسان با آن‌ها گناه کند؛ بلکه باید او را از حرام دورنگه دارند. به‌عبارت‌دیگر، هدف خلقت انسان همین است.\nحَتَّی إِذَا قَامَ اعْتِدَالُهُ وَاسْتَوَی مِثَالُهُ\nو آنگاه که جوانی او به حدّ کمال رسید و بر پای خویش استوار ماند.\nاین انسان به نهایت کمال جسمانی خود رسید؛ بیش از آن رشد نمی‌کرد و از این سن به بعد، کم‌کم به‌سوی زوال و خمیدگی می‌رفت. انسان باید در برابر همه‌ی این نعمت‌ها خاضع و خاشع باشد.\nنَفَرَ مُسْتَکبِرًا\nگردن‌کشی آغاز کرد و از خدا روی گرداند.\nبه خدا پشت کرد، درحالی‌که مستکبر و گردن‌کش بود. گمان کرد از خدا بی‌نیاز شده است.\nوَخَبَطَ سَادِرًا\nو در بیراهه گام نهاد.\nبی‌پروا راه را کج کرد و انحراف را در پیش گرفت، بدون اینکه به آن توجه کند.\nمَاتِحًا فِی غَرْبِ هَوَاهُ\nدر هواپرستی غرق شد.\nانسانی که به جایگاه قدرت و زیبایی ظاهری رسیده است، با دلو بزرگی از چاه مسموم وجودش شهوت بالا می‌کشد و دست‌بردار هم نیست. جوان بود و خدا به او قدرت داده بود تا مسیر درست را انتخاب کند.\nکادِحًا سَعْیا لِدُنْیاهُ\nو برای به‌دست‌آوردن لذت‌های دنیا تلاش فراوان کرد.\nتمام سعی و تلاشش برای به‌دست‌آوردن دنیاست؛ گویی آخرتی وجود ندارد. همه‌ی وقت و انرژی‌اش را صرف دنیا کرده است.\nفِی لَذَّاتِ طَرَبِهِ وَبَدَوَاتِ أَرَبِهِ\nو سرمست شادمانی دنیا شد.\nغرق در لذت‌های دنیا و خوشی‌های زودگذر آن بود؛ به‌اصطلاح، هرچه پیش آمد، خوش آمد. یعنی به هیچ گناهی دست رد نمی‌زد و از هر خلاف و گناهی استقبال می‌کرد.\nثُمَّ لَا یحْتَسِبُ رَزِیةً\nهرگز گمان نمی‌کرد مصیبتی پیش بیاید.\nاین جوان که این‌گونه غرق در شهوت و گناه و بی‌دینی و لاابالی‌گری بود، اصلاً حساب نمی‌کرد که روزی گرفتاری برایش پیش بیاید. فکر می‌کرد همیشه همین‌طور جوان و زیبا و قدرتمند خواهد ماند. خیال نمی‌کرد روزی گرفتار شود و قدرتش تحلیل برود.\nوَلَا یخْشَعُ تَقِیةً\nو بر اساس تقوا فروتنی نداشت.\nیک‌بار هم نشد که از روی تقوا از خدا بترسد. گاهی اگر گناهی را کنار می‌گذاشت، از روی تقوا و خداترسی نبود؛ بلکه برای حفظ آبروی خودش بود. برای خدا گناه را ترک نمی‌کرد. هیچ خضوع و خشوعی در کار نبود؛ بلکه این نفسانیت بود که گاهی او را از گناه دور می‌کرد.\nفَمَاتَ فِی فِتْنَتِهِ غَرِیرًا\nناگهان، درحالی‌که در این آزمایش چندروزه سرمست و مغرور بود، مرگ او را ربود.\nزمان کوچ کردن رسید. مرد، درحالی‌که غرق در غرور و خودبزرگ‌بینی بود. در اوج قدرت و بی‌توجهی به مرگ، مرگ یقه‌اش را گرفت.\nوَعَاشَ فِی هَفْوَتِهِ یسِیرًا\nدر دل بدبختی‌ها اندکی زندگی کرد.\nدرحالی‌که همه‌ی زندگی‌اش غرق در لغزش و گناه بود. ممکن نیست کسی تمام عمرش را در گناه و باطل بگذراند و در آخرین روز توبه کند. کسانی هم که در پایان کار بازگشتند، از ابتدا راهی برای بازگشت باقی گذاشته بودند و همه‌ی پل‌های پشت سرشان را خراب نکرده بودند. اگر حُرّ بازگشت، به‌خاطر احترامی بود که از ابتدا برای حضرت فاطمه‌ی زهرا (س) داشت. او از ابتدا چنین زمینه‌ای داشت و در پایان کار عاقبت‌به‌خیر شد.\nلَمْ یفِدْ عِوَضًا وَلَمْ یقْضِ مُفْتَرَضًا\nو آنچه را ازدست‌داده بود، عوضی به دست نیاورد و آنچه از واجبات را ترک کرده بود، قضا نکرد.\nدر برابر عمری که ازدست‌داده بود، چیزی به دست نیاورد. هیچ توشه و بهره‌ای نبرد و هیچ‌یک از اعمال واجبش را نیز به‌جا نیاورد. کسی که یک‌عمر در خطا و انحراف حرکت کرده است، در لحظه‌ی آخر احتضار دیگر توبه‌اش پذیرفته نمی‌شود. اگر کسی در طول عمر، صالحانه زندگی کند، در آخرت نیز زندگی خوبی خواهد داشت.\nدَهِمَتْهُ فَجَعَاتُ الْمَنِیةِ فِی غُبَّرِ جِمَاحِهِ وَسَنَنِ مِرَاحِهِ\nدردها و سختی‌های مرگ او را فراگرفت. روزها را در حیرت و سرگردانی و شب‌ها را با بیداری و نگرانی می‌گذراند.\nحضرت حالات احتضار را بیان می‌کند. مرگ از هر طرف او را فراگرفته است، اما همچنان سرکشی و گردن‌کشی در وجودش باقی‌مانده است. قدم‌زدن و حرکت‌کردن در مسیر باطل نیز همچنان برای او ادامه دارد.\nفَظَلَّ سَادِرًا وَبَاتَ سَاهِرًا فِی غَمَرَاتِ الْآلَامِ وَطَوَارِقِ الْأَوْجَاعِ وَالْأَسْقَامِ\nهر روز به‌سختی درد می‌کشد و هر شب رنج و بیماری به سراغش می‌آید.\nمرگ او را حیران می‌کند؛ کاری با او می‌کند که خودش را نشناسد. دیگر چیزی از امور دنیوی به یادش نمی‌ماند. چنان حیران می‌شود که حتی نام خود را نیز فراموش می‌کند. کار از کار گذشته است. انسانی که تا دیروز امرونهی می‌کرد، اکنون شب‌وروز آرام و قرار ندارد.\nبَینَ أَخٍ شَقِیقٍ وَوَالِدٍ شَفِیقٍ\nدر میان برادری غمخوار و پدری مهربان.\nپدر و برادران و دوستان و آشنایان و خانواده، همه دور او را گرفته‌اند.\nوَدَاعِیةٍ بِالْوَیلِ جَزَعًا وَلَادِمَةٍ لِلصَّدْرِ قَلَقًا\nدرحالی‌که زنی از روی بی‌تابی فریاد «وای» سر می‌دهد و دیگری از روی اضطراب بر سینه می‌کوبد.\nهمسر اوست که فریاد می‌زند و آه می‌کشد. مادرش به سینه می‌کوبد؛ اما دیگر فایده‌ای ندارد.\nوَالْمَرْءُ فِی سَکرَةٍ مُلْهِثَةٍ\nو اما او در حالت بیهوشی و سکرات مرگ است.\nدرحالی‌که اطرافیانش دور او را گرفته‌اند، خودش در حالت بیهوشی به سر می‌برد. سکرات مرگ آن‌قدر شدید است که گویی انسان چیزی نمی‌فهمد. البته از دید ما چنین به نظر می‌رسد.\nوَغَمْرَةٍ کارِثَةٍ\nو در رنجی است که شدید است و انسان را از پا درمی‌آورد.\nوَأَنَّةٍ مُوجِعَةٍ\nدر حالتی است که ناله می‌زند؛ ناله‌ای دردناک که دیگران نیز از شنیدن آن اندوهگین می‌شوند.\nوَجَذْبَةٍ مُکرِبَةٍ\nدرد جان‌کندن در او شدت می‌گیرد.\nوَسَوْقَةٍ مُتْعِبَةٍ\nاحتضار او رنج‌آور است. هرچه فریاد می‌زند، کسی به دادش نمی‌رسد. می‌بیند همه بالای سرش اشک می‌ریزند و درمی‌یابد که دیگران از نجات او درمانده‌اند.\nدرد دیگر او، رفتن، دیدن مَلَکِ عذاب و مشاهده‌ی نتایج اعمال خویش است. همه‌ی این رنج‌ها با هم به جان او افتاده‌اند و دیگر بازگشتی در کار نیست.\nثُمَّ أُدْرِجَ فِی أَکفَانِهِ مُبْلِسًا\nپس از مرگ، او را درحالی‌که مأیوس است، در کفن پیچیدند.\nخودش می‌فهمد که کار تمام شده است و اطرافیان نیز درمی‌یابند که دیگر کاری از دست کسی برنمی‌آید.\nوَجُذِبَ مُنْقَادًا سَلِسًا\nو درحالی‌که تسلیم و آرام بود، او را حرکت دادند.\nدیگر نمی‌تواند چیزی بگوید. کار به دست دیگران افتاده است. تمام اختیارش ازدست‌رفته و دیگر کاری از او برنمی‌آید.\nثُمَّ أُلْقِی عَلَی الْأَعْوَادِ رَجِیعَ وَصَبٍّ\nسپس او را بر چوب‌های تابوت نهادند؛ درحالی‌که بیماری، رنجی طولانی بر او نشانده و آثار بیماری درازمدت بر چهره‌اش نمایان بود.\nوَنِضْوَ سَقَمٍ\nخسته و لاغر به سفر آخرت می‌رود.\nتَحْمِلُهُ حَفَدَةُ الْوِلْدَانِ وَحَشَدَةُ الْإِخْوَانِ\nفرزندان و دوستان و آشنایان، تابوت او را حرکت می‌دهند.\nإِلَی دَارِ غُرْبَتِهِ\nتا سرمنزل غربت.\nاو را به سرزمینی حمل می‌کنند که خانه‌ی غربت و تنهایی است.\nوَمُنْقَطَعِ زَوْرَتِهِ\nو به جایی می‌برند که هیچ‌کس نمی‌تواند او را زیارت کند. در آخرین لحظه، بند کفن را باز می‌کنند و برای آخرین بار او را می‌بینند؛ اما پس از آن، دیگر زیارتی در کار نیست.\nوَمُفْرِدِ وَحْشَتِهِ\nآنجا که جایگاه وحشت است، او را پیش می‌برند و تنها با اعمال خود رها می‌شود.\nحَتَّی إِذَا انْصَرَفَ الْمُشَیعُ\nتا زمانی که تشییع‌کنندگان یکی‌یکی از کنار قبر بازگردند.\nوَرَجَعَ الْمُتَفَجِّعُ\nو مصیبت‌زدگان بازگردند.\nهمان‌هایی که تا چند دقیقه‌ی قبل گریه می‌کردند، بازمی‌گردند.\nأُقْعِدَ فِی حُفْرَتِهِ نَجِیا لِبَهْتَةِ السُّؤَالِ وَعَثْرَةِ الِامْتِحَانِ\nاو را در گودال قبر می‌نشانند تا با پرسشی حیرت‌آور و امتحانی لغزش‌زا روبه‌رو شود و با زمزمه‌ای غم‌آلود سخن بگوید.\nاین فرد می‌ماند و پرسش‌وپاسخ قبر. به‌خاطر شدت این حالت، مبهوت می‌شود و دست‌وپایش را گم می‌کند. زبانش بند می‌آید. اینجا جایگاه حقیقت است و جای دروغ و گزافه‌گویی نیست.\nاین ملکات وجودی او هستند که سخن می‌گویند: مبهوت و حیران و سرگردان باش؛ چون در امتحان لغزش داشتی و سربلند بیرون نیامدی.\nامام صادق (ع) می‌فرمایند: از شیعیان ما نیست کسی که سه چیز را انکار کند: معراج، سؤال شب اول قبر و شفاعت اهل‌بیت (ع)؛ بنابراین، این امور از ملزومات مسلمان و شیعه بودن است.\nعلامه مجلسی (ره) می‌فرماید:\nشب اول قبر برای مؤمن خالص، کافر خالص و منافق خالص است و بقیه‌ی افراد وارد برزخ می‌شوند و در آنجا به حسابشان رسیدگی می‌شود.\nشب اول قبر همان شبی است که انسان از دنیا می‌رود و ارتباطی با داشتن یا نداشتن قبر ظاهری ندارد.\nاین مسئله به برزخ مربوط است و ارتباطی به جسم ندارد؛ انسان در برزخ مورد پرسش‌وپاسخ قرار می‌گیرد.\nاللَّهُمَّ أَخْرِجْ حُبَّ الدُّنْیا مِنْ قُلُوبِنَا","بخش هفتم\nمتن:\nوَ أَعْظَمُ مَا هُنَالِكَ بَلِيَّةً نُزُولُ الْحَمِيمِ وَ تَصْلِيَةُ الْجَحِيمِ وَ فَوْرَاتُ السَّعِيرِ وَ سَوْرَاتُ الزَّفِيرِ، لَا فَتْرَةٌ مُرِيحَةٌ وَ لَا دَعَةٌ مُزِيحَةٌ وَ لَا قُوَّةٌ حَاجِزَةٌ وَ لَا مَوْتَةٌ نَاجِزَةٌ وَ لَا سِنَةٌ مُسَلِّيَةٌ بَيْنَ أَطْوَارِ الْمَوْتَاتِ وَ عَذَابِ السَّاعَاتِ إِنَّا بِاللَّهِ عَائِذُونَ.\nعِبَادَ اللَّهِ، أَيْنَ الَّذِينَ عُمِّرُوا فَنَعِمُوا وَ عُلِّمُوا فَفَهِمُوا وَ أُنْظِرُوا فَلَهَوْا وَ سُلِّمُوا فَنَسُوا؟ أُمْهِلُوا طَوِيلًا وَ مُنِحُوا جَمِيلًا وَ حُذِّرُوا أَلِيماً وَ وُعِدُوا جَسِيماً. احْذَرُوا الذُّنُوبَ الْمُوَرِّطَةَ وَ الْعُيُوبَ الْمُسْخِطَةَ. أُولِي الْأَبْصَارِ وَ الْأَسْمَاعِ وَ الْعَافِيَةِ وَ الْمَتَاعِ، هَلْ مِنْ مَنَاصٍ أَوْ خَلَاصٍ أَوْ مَعَاذٍ أَوْ مَلَاذٍ أَوْ فِرَارٍ أَوْ مَحَارٍ أَمْ لَا؟ فَأَنَّى تُؤْفَكُونَ، أَمْ أَيْنَ تُصْرَفُونَ، أَمْ بِمَا ذَا تَغْتَرُّونَ؟ وَ إِنَّمَا حَظُّ أَحَدِكُمْ مِنَ الْأَرْضِ ذَاتِ الطُّوْلِ وَ الْعَرْضِ قِيدُ قَدِّهِ [مُنْعَفِراً] مُتَعَفِّراً عَلَى خَدِّهِ. الْآنَ عِبَادَ اللَّهِ وَ الْخِنَاقُ مُهْمَلٌ وَ الرُّوحُ مُرْسَلٌ فِي فَيْنَةِ الْإِرْشَادِ وَ رَاحَةِ الْأَجْسَادِ وَ بَاحَةِ الِاحْتِشَادِ وَ مَهَلِ الْبَقِيَّةِ وَ أُنُفِ الْمَشِيَّةِ وَ إِنْظَارِ التَّوْبَةِ وَ انْفِسَاحِ الْحَوْبَةِ، قَبْلَ الضَّنْكِ وَ الْمَضِيقِ وَ الرَّوْعِ وَ الزُّهُوقِ وَ قَبْلَ قُدُومِ الْغَائِبِ الْمُنْتَظَرِ وَ إِخْذَةِ الْعَزِيزِ الْمُقْتَدِرِ.\nقال الشريف: و في الخبر أنه (علیه السلام) لمّا خَطب بهذه الخطبة اقشعرّت لها الجُلود و بَكت العيون و رَجفت القلوب و من الناس من يُسمّي هذه الخطبة الغرّاء.\nترجمه:\nبزرگترين بلايى كه در اين مرحله است، بلاى آن آب جوشان و دخول در دوزخ فروزان است و وحشت از فوران و شدت صداى آتش. عذاب كاهش نمى يابد تا اندكى بيارامد و آسايشى نيست، كه رنج را بزدايد و توان و طاقتى نه، كه مگر عذاب را بازدارد، و مرگى نيست كه از رنج برهاندش و نه به قدر لحظه اى خواب، كه اندكى غمش را تسكين دهد به انواع مرگ ها و عذابهاى پياپى همچنان مبتلاست. و ما به خدا پناه مى بريم.\nاى بندگان خدا! کجا هستند کسانى که عمر طولانى به آنها داده شد و در ناز و نعمت به سر مى بردند (امّا قدر آن را ندانستند) و آنها که تعليم داده شدند و فهميدند (ولى هرگز به آن عمل نکردند) و کسانى که به آنان مهلت داده شد (تا به اصلاح اعمال خويش بپردازند) ولى به بيهوده کارى پرداختند و آنها که سلامت نصيبشان شد، ولى اين نعمت بزرگ را فراموش کردند (و هيچ گاه شکر آن را به جا نياوردند). (آرى) به آنها براى مدّت طولانى مهلت داده شد و نعمت هاى زيبا در اختيارشان قرار گرفت. آنان را از کيفر گناهانشان بر حذر داشتند (تا از آن بپرهيزند) و پاداش هاى بزرگ (در برابر اطاعت فرمان خدا) به آنها وعده داده شد (ولى آن را نيز به فراموشى سپردند) بترسيد از گناهانى که انسان را به هلاکت مى افکند! و از عيوبى که موجب خشم پروردگار است!\nاى صاحبان چشم و گوش بينا و شنوا، و اى دارندگان عافيت و امکانات و متاع دنيا! آيا هيچ راه گريز يا خلاص و پناهگاه و قلعه محکم، و يا فرار و بازگشتى وجود دارد، يا نه؟ حال «چگونه (از راه حق) منحرف مى شويد!» يا به کجا مى رويد! يا به چه چيز مغرور مى شويد؟! اين در حالى است که بهره هر يک از شما از زمين، با اين طول و عرضش، تنها به اندازه قامت او است، در حالى که گونه اش بر خاک ساييده مى شود!\nاى بندگان خدا! هم اکنون که ريسمان مرگ بر گلوى شما نيفتاده و روح (براى بدست آوردن کمالات) آزاد است و بدنها راحت، و مى توانيد با کمک يکديگر مشکلات را حل کنيد و هنوز مهلتى داريد و فرصت براى تصميم گرفتن باقى است و راه توبه و بازگشت از گناه باز است (از اين فرصت هاى گرانبها استفاده کنيد!) پيش از آنکه در سختى و تنگنا و ترس و نابودى قرار گيريد و پيش از فرا رسيدن مرگى که در انتظار است و قبل از آنکه دست قدرتِ خداوندِ قوىّ مقتدر، شما را بگيرد (آرى پيش از همه اينها، فرصت را مغتنم بشمريد و زاد و توشه برگيريد).\nتفسیر:\n   خطبه‌الغرّاء\nاین خطبه جزو خطبه‌های تأثیرگذار حضرت است. ابن ابی‌الحدید معتزلی می‌گوید: بعد از کلام خدا و پیامبر، هیچ عربی نمی‌تواند این‌گونه و به این زیبایی کلمات را استخدام کند؛ مانند تیرانداز ماهری که تیر را دقیقاً به هدف می‌زند، حضرت هم کلمات را دقیقاً و آن‌گونه که می‌خواهد و هدف دارد، ایراد کرده‌اند. عنصر محوری این خطبه تقواست.\nوَأَعْظَمُ هُنَالِک الْبَلِیةَ نُزُولُ الْحَمِیمِ\nوقتی میت از این دنیا رفت، وارد برزخ می‌شود. لحظه جان‌دادن بسیار سخت است؛ شب اول قبر، سؤال‌وجواب سخت، و از همه اینها سخت‌تر آن بلایی است که در برزخ بر میت وارد می‌شود و آن نزول حمیم است؛ آب سوزانی که به خورد او می‌دهند. آن‌قدر سخت که احتضار و سؤال‌وجواب فراموش می‌گردد. از همین‌جا عذاب شروع می‌شود: «القبر حفرهٌ مِن حُفَرِ النیران او روضهٌ من ریاضِ الجنه». قبر یا باغی از بهشت است یا حفره‌ای از جهنم. «النار یعرضون علی‌ها غدوا وعشیا ویوم تقوم الساعه ادخلوا آل فرعون اشد العذاب غافر - ۴۶» بر آل فرعون صبح و شب عذاب شدید نازل کنید. همه عذاب‌ها برای برزخ است و عذاب شدیدتر در قیامت بر آل فرعون نازل می‌شود. قبل از قیامت و در برزخ هم آل فرعون مورد عتاب هستند.\nوَتَصْلِیةُ الْجَحِیمِ\nورود آنها به آتش است. قرآن کریم در مورد به آتش افتادن شخص سه تعبیر دارد. در بخشی از آیات فرموده: «الذی یصلی النار الکبری».\n۱- آتش از بیرون شخص جهنمی را می‌سوزاند. «وتصلیه الجحیم»\n۲- این شخص از درون می‌سوزد؛ تصلیه باب تفعیل دلالت بر شدت دارد. «نار الله الموقده التی تتطلع علی الافئده»\n۳- منبع آتش خودِ شخص است؛ شخص آتش می‌شود، هم می‌سوزد و هم دیگران را می‌سوزاند. هرکدام یک مرحله است؛ ولی قرآن هر سه مرحله را بیان کرده است. هر چه گناه بیشتر، آتش از برون به درون می‌رود و در درون به آتشی تبدیل می‌شود که نیاز به هیزم ندارد. خود، آتش می‌شود؛ هم می‌سوزد، هم دیگران را می‌سوزاند.\nوَفَوَراتِ السَّعِیرِ وَسُوَراتِ الزَّفِیرِ\nفوران‌کردن شعله آتش است. یک سختی و رنج مضاعف از جهنم و با صدای تند شدید [سورات] آتش همراه است.\nلَا فَتْرَةَ مُرِیحَةً وَلَا دَعَةً مُزِیحَةً\nجهنم مثل دنیا نیست. در دنیا امید شفا یا در نهایت با مردن، راه رهایی هست. در قیامت یک‌لحظه راحتی [مریحه] نیست و آرامشی که غصه را برطرف کند [مزیحه] نیست.\nوَلَا قُوَّةَ حَاجِزَةً وَالْمَوْتَةَ نَاجِزَةً\nانسان گرفتار در جهنم قوه دفاع در مقابل آتش ندارد [حاجزه]. مرگ در کار نیست که این شخص را از عذاب آخرت راحت کند [ناجزه]. تفاوت آتش دنیا و آخرت در این است. آتش دنیا یا درمان می‌شود یا مسکن دارد یا نهایت می‌میرد و راحت می‌شود؛ ولی عذاب و آتش آخرت علی‌الدوام است و خلاصی در کار نیست. لحظه‌به‌لحظه درد تازگی دارد و می‌فهمد، چون بی‌حسی ندارد.\nوَلَا سِنَةٌ مُسْلِیةٌ\nیک‌لحظه چرت‌زدن در کار نیست [لاسنه] که از درد و غصه برهاند و دقایقی از هول و اضطراب نجات دهد. شلاق خوردن در دنیا بعد از چند ضربه، بدن سِر و بی‌حس می‌شود؛ ولی در آخرت همه ضربه‌ها حس می‌شوند و تازگی دارند.\nبَینَ أَطْوَارِ الْمَوْتَاتِ\nانواع‌واقسام مرگ بر او عارض می‌شود. نمی‌میرد، آن‌قدر زجر می‌کشد که گویی می‌خواهد بمیرد… در جمله قبل فرمود: «لا موته ناجزه». در قیامت مرگ در کار نیست. این جمله انواع مرگ را ذکر کرده‌اند. انواع‌واقسام مرگ است؛ می‌سوزد و می‌میرد و دوباره زنده می‌شود. «ویَاتیهِ الموتِ مِن کلِ مَکانٕ وماهو بمیتٕ ابراهیم - ۱۷» مرگ از هر طرف به سمت او می‌آید، درحالی‌که مردن در کار نیست. این مرگ‌ها چیست که از هر طرف هجوم می‌آورد؟\nوَعَذَابِ السَّاعَاتِ\nمرگ و عذاب لحظه‌به‌لحظه و به اشکال مختلف بر این فرد عارض می‌شود.\nإِنَّا بِاللَّهِ عَائِذُونَ\nما پناه می‌بریم به خدا از این عذاب‌های سخت که دچار شویم… کدام گناه از ما صادر شده که سزاوار هزاران مرگ است، ولی نمی‌میریم؛ می‌میریم و زنده می‌شویم.\n✅ کیفیت مرگ، چگونگی سؤال‌وجواب، و کیفیت قبر برای شما گفته شد. از شما سؤالی دارم: گذشتگانی که عمر طولانی و آن‌همه نعمت به آنها داده شده بود، اما از آن بهره‌ای نبردند، اکنون کجا هستند؟!! آیا جایی غیر از جهنم دارند؟!!\nعِبَادَ اللَّهِ أَینَ الَّذِینَ عُمِّرُوا فَنَعِمُوا\nای بندگان خدا! کسانی که خدا عمر و نعمت طولانی به آنها داد، کجا هستند؟\nوَعُلِّمُوا فَفَهِمُوا\nکجا هستند کسانی که به آنها آموخته شد و فهمیدند؛ ولی زیر بار نرفتند. قرآن و حقانیت آن را شنیدند و قبول نکردند. جایگاه علی را دیدند و در مقابل این علم و فهم عمل نکردند.\nوَانْظُرُوا فَلَهُوا\nکجا هستند کسانی که مهلت به آنها داده شد، اما دنبال لهو و بازی بودند!\nوَسَلِمُوا فَنَسُوا\nکجا هستند کسانی که به آنها سلامتی و جسم سالم داده شد؛ ولی فراموش کردند!\nأُمْهِلُوا طَوِیلًا وَمُنِحُوا جَمِیلًا\nعمر طولانی و نعمت‌های زیبا به آنها داده شد.\nوَحُذِّرُوا أَلِیمًا وَوُعِدُوا جَسِیمًا\nبه آنها انذار داده شد، از ترس و عذاب قبر و قیامت برحذر داشته شدند و به نعمت‌های بزرگ وعده داده شدند. اگر گناه نکنید، انواع‌واقسام نعمت حلال و بهشت به شما داده خواهد شد. اما نخواستند. عباد الله، شما از آنها عبرت بگیرید. نعمت و قدرت آنها از شما بیشتر بود؛ اکنون کجا هستند! شما جایگاه قبلی‌ها را بنگرید، در چه حالی هستند؟!\nاِحْذَرُوا الذُّنُوبَ الْمُورِطَةَ\nبرحذر باشید و بترسید از گناهانی که هلاک‌کننده [مورطه] هستند. مواظب گناه باشید که روح را می‌کشد. گناه مرگ فطرت و وجدان، و تفکر و انسانیت را می‌کشد. گناه هلاک‌کننده است. فقط مرگ جسمانی نیست؛ مرگ روح است.\nوَالْعُیوبَ الْمُسْخِطَةَ\nبعضی عیوب موجب خشم و عذاب الهی هستند. مراقب عیوب اخلاق باشید که خدا نسبت به آنها حساس است. گاهی کسی سهواً دروغ می‌گوید و گاهی عمدی. این عمدی بودن موجب خشم خدا می‌شود. کسب هم دو گونه است: در بعضی کسب‌ها کاسب حاکم است و اختیار بر درآمد دارد؛ ولی در بعضی دیگر، درآمد بر انسان حاکم است. اخلاق از این نوع است. کسی که خوش‌اخلاقی را منش خود می‌کند، خوش‌اخلاقی او را به همه‌جا می‌کشد. اول کسب می‌کند، بعد از مدتی اخلاق بالای سر او حاکم می‌شود. حضرت فرمودند بپرهیزید؛ فردای قیامت ملکات انسان حرف می‌زند. چه ملکۀ خوش‌اخلاقی باشد و چه غرور و دروغ. قیامت زبان‌بسته است؛ این زبان حال و ملکات وجود است که بلند سخن می‌گوید.\nیا أُولِی الْأَبْصَارِ وَالْأَسْمَاعِ\nای مردمی که صاحب چشم و گوش و هوش هستید.\nوَالْعَافِیةِ وَالْمَتَاعِ\nکسانی که سلامت هستید و متاع و امکانات دنیا در دست شماست. کالای دنیا در اختیار شما بود و هرطور خواستید عمل کردید.\nهَلْ مِنْ مَنَاصٍ أَوْ خَلَاصٍ\nامروز قدرت در دست شماست؛ آیا فردای قیامت راهی برای خلاص و راه نجات [مناص] از جهنم دارید؟! آیا می‌توان خدا را دور زد و راه دررو و فرار وجود دارد؟!\nأَوْ مَعَاذٍ أَوْ مَلَاذٍ أَوْ فِرَارٍ أَوْ مَحَارٍ أَمْ لَا؟\nآیا پناهگاهی [معاذ] جز اعمال انسان هست؟! آیا جهنم جایی برای پنهان‌شدن [ملاذ] دارد؟! آیا قیامت جای فرار دارد؟! آیا راه بازگشت [محار] دارد؟! می‌توانید به دنیا برگردید یا نه؟ همه چیز در عمل انسان است. مناص و خلاص، عمل است.\nفَأَنَّیٰ تُؤْفَکونَ؟ أَمْ أَینَ تُصْرَفُونَ؟\nاز راه خدا به کجا می‌روید؟ مسیری که منحرف کردید، سر از کجا درمی‌آورد؟ به کجا برمی‌گردید؟! [تصرفون]\nأَمْ بِمَاذَا تَغْتَرُّونَ؟\nبه چه چیز فریفته شده‌اید؟ چه دارید که شما را فریفته است؟ عمر ابدی دارید، یا قدرت و علم بی‌نهایت، یا توشه راه، یا توان مقابله با آتش؟ هیچ‌کدام که نیست. پس چرا در برابر حرف و احکام خدا ایستادگی می‌کنید؟\nوَإِنَّمَا حَظَّ أَحَدِکمْ مِنَ الْأَرْضِ ذَاتِ الطَّوْلِ وَالْعَرْضِ قَیدَ قَدِّهِ\nدرحالی‌که قطعاً همه سهم شما از زمینی که با تبختر و گردن‌کشی در آن زندگی می‌کنید، به‌اندازه طول و عرض [ذات طَول] بدن شماست. به‌اندازه قد شماست [قید قده]. یک جایی از زمین که فقط بدن را خاک کنند و آن هم به‌زودی می‌پوسد و چیزی نمی‌ماند.\nمُتَعَفِّرًا عَلَیٰ خَدِّهِ\nدرحالی‌که صورت و گونه [خد] خاک‌مال می‌شود [متعفرا]. میت را حتی طاق‌باز هم نمی‌گذارند که سطح بیشتری از زمین داشته باشد. (کنایه از به پهلو خواباندن میت است.)\nأَلَاٰنَ عِبَادَ اللَّهِ وَالْخِنَاقِ مُهْمَلٌ وَالرُّوحُ مُرْسَلٌ فِی فِینَةِ الْإِرْشَادِ\nبندگان خدا، هم‌اکنون را دریابید. گذشته‌ها گذشته، آینده هم نیامده؛ حال را دریابید. هنوز طناب مرگ دور گردن شل است و محکم کشیده نشده؛ حال را مراقب باشید. انسان از لحظه به‌دنیاآمدن، پای چوبه‌دار «مرگ» است. طناب مرگ دور گردن شماست؛ تا روح آزاد است، کاری کنید. «ما فاتَ مَضیٰ وما سَیَاتیکَ فاَینَ قُم فَاغتَنِمِ الفُرصَهِ بینَ العَدَمَینِ». گذشته‌ها گذشته، آینده هم نامعلوم؛ بپا خیزید و فرصت کنونی را دریابید. هنوز روح آزاد [مرسل] و هنوز فرصت هدایت‌شدن [رشاد] است. راه هدایت باز است.\nوَرَاحَةِ الْأَجْسَادِ\nالان می‌توانید کاری کنید. جسم و بدن سالم است؛ فردا که مرگ رسید، بدن آزاد نیست و در گرو زمین است. امروز را مراقبت کنید.\nوَبَاحَةِ الِاحْتِشَادِ\nاکنون که در حیات [باحه] زندگی می‌توانید در میدان اجتماع [احتشاد] خدماتی داشته باشید. با مشورت و دست‌به‌دست هم دادن، مشکل کسی را حل کنید. با مشاوره، مشکل فکری و اخلاقی خود را برطرف کنید.\nوَمَهَلِ الْبَقِیةِ\nهنوز مهلت باقی است و مهر انقضا به پرونده نخورده است.\nوَأُنُفِ الْمَشِیةِ\nاکنون ابتدای اراده [مُشیه] است. با یک العفو می‌توان هشتاد سال عمر را جبران کرد. هر جای عمر که باشد، تا فرصت مرگ به خط پایان نرسیده، هنوز اول اراده‌کردن است. خوبی این مسیر این است که هفتاد سال عمر تباه‌شده با هفتاد سال توبه سپری نمی‌شود؛ بلکه با یک آه و از عمق و سوز جان، نه‌تنها عفو می‌کند، بلکه به حسنات مبدل می‌کند. همه اینها نشانه رحمت و فرصت است تا وقتی به پایان خط نرسیده، می‌توان گذشته را اصلاح کرد. «مبدل السیات بالحسنات» خدا تبدیل به حسنات می‌کند.\nوَانْظَارِ التَّوْبَةِ وَانْفِسَاحِ الْحَوْبَةِ\nهنوز فرصت توبه باقی است. هنوز فرصت و گستردگی [انفساح] برای عرض حاجت [حوبه] به خدا زیاد است. زبان برای عرض حاجت؛ در هر کاری از خدا کمک بگیرید. خدا منتظر دستگیری است.\nقَبْلَ الضَّنْک وَالْمَضِیقِ\nقبل از اینکه گرفتار سختی و تنگیِ لحظات مرگ فرابرسد.\nوَالْرَّوْعِ وَالزُّهُوقِ\nقبل از ترس‌های قیامت و قبل از هلاکت و نابودی [زهوق]، به فکر خود باشید.\nوَقَبْلَ قُدُومِ الْغَائِبِ الْمُنْتَظَرِ\nقبل از اینکه آن غایبِ منتظر فرابرسد؛ یعنی آن چیزی که غایب است و هر لحظه انتظار آمدن آن می‌رود [مرگ]. قبل از اینکه مرگ برسد، جای توبه باقی‌ست.\nوَأَخْذِ الْعَزِیزِ الْمُقْتَدِرِ\nقبل از اینکه خدای عزیز و مقتدر بیخ گلو را بگیرد و مؤاخذه کند، فرصت توبه و حاجت هست.\n✳️ وَفِی الْخَبَرِ أَنَّهُ عَلَیهِ السَّلَامُ لَمَّا خَطَبَ بِهَذِهِ الْخُطْبَةِ اقْشَعَرَّتْ لَهَا الْجُلُودُ وَبَکتِ الْعُیونُ وَرَجِفَتِ الْقُلُوبُ وَمِنَ النَّاسِ مَنْ یسَمِّی هَذِهِ الْخُطْبَةَ الْغَرَّاءَ\nمرحوم سیدرضی (رحم الله) می‌فرماید: در روایت و اخبار آمده وقتی حضرت این خطبه را شروع کردند و هرچه خطبه پیش می‌رفت، بدن‌ها به لرزه درمی‌آمد و اشک از چشم‌ها سرازیر می‌شد و قلب‌ها می‌لرزید. قلب‌ها متمایل به خدا شده بود. این خطبه آن‌قدر در بین ناس معروف و مشهور بود که هرکه آن را می‌شنید، می‌گفت خطبه غرایی است. \nاللَّهُمَّ اجْعَلْ عَوَاقِبَ أُمُورِنَا خَیرًا"]});
